Object.assign(window.IND_FEED_BODY, {"st-fk.dhola-maru":{"route":"#/story/fk.dhola-maru","art":"art/story/fk-dhola-maru.jpg","cta":"Read the story","src":"story:fk.dhola-maru:scenes:0:text","title":"Dhola, Maru and the Wind-Swift Camel","body":"The singers of Rajasthan have a story they have sung for centuries, in the long ballad called Dhola-Maru.","why":"From The Western Lands"},"sh-fk.dhola-maru":{"route":"#/story/fk.dhola-maru","art":null,"cta":"Read the story","src":"story:fk.dhola-maru:hook","title":"Dhola, Maru and the Wind-Swift Camel","body":"A forgotten promise, a singer who would not give up, and a camel that ran like the desert wind — Rajasthan's favourite chase.","why":"From The Western Lands"},"sm-fk.dhola-maru":{"route":"#/story/fk.dhola-maru","art":null,"cta":"Read the story","src":"story:fk.dhola-maru:scenes:4:text","title":"Dhola, Maru and the Wind-Swift Camel — the middle","body":"Across the Thar he rode — days of dunes, wells found by starlight, the camel's great feet spooning the sand — and reached Pugal at last, where Maru met the promise-keeper's reward: the person she had believed in, finally standing in the doorway, extremely dusty.","why":"A moment from Dhola, Maru and the Wind-Swift Camel"},"sl-fk.dhola-maru":{"route":"#/story/fk.dhola-maru","art":null,"cta":"Read the story","src":"story:fk.dhola-maru:moral","title":"What Dhola, Maru and the Wind-Swift Camel says","body":"A promise is a road — someone must keep walking it, and then it carries you home.","why":"The story’s own lesson"},"sp-fk.dhola-maru":{"route":"#/story/fk.dhola-maru","art":null,"cta":"Read the story","src":"story:fk.dhola-maru:place:0","title":"Dhola, Maru and the Wind-Swift Camel","play":{"q":"Which place on the map does this story light up?","opts":["Rajasthan","Uttarakhand","Dadra & Nagar Haveli"],"a":0,"after":"It lights up Rajasthan."},"why":"A map question"},"st-fk.pabuji-camels":{"route":"#/story/fk.pabuji-camels","art":"art/story/fk-pabuji-camels.jpg","cta":"Read the story","src":"story:fk.pabuji-camels:scenes:0:text","title":"How the Camels Came to the Desert","body":"In the villages of the Thar, when night falls, a bhopa — a singer-priest — sometimes unrolls a painted scroll as long as a house wall, lights a lamp, and begins to sing the epic of Pabuji: the folk hero of the desert, protector of herds, keeper of impossible promises.","why":"From The Western Lands"},"sh-fk.pabuji-camels":{"route":"#/story/fk.pabuji-camels","art":null,"cta":"Read the story","src":"story:fk.pabuji-camels:hook","title":"How the Camels Came to the Desert","body":"A wedding gift was promised: strange, humped animals from beyond the desert that no one in Rajasthan had ever herded. Someone had to go and fetch them.","why":"From The Western Lands"},"sm-fk.pabuji-camels":{"route":"#/story/fk.pabuji-camels","art":null,"cta":"Read the story","src":"story:fk.pabuji-camels:scenes:4:text","title":"How the Camels Came to the Desert — the middle","body":"Kelam got her wedding gift, and the desert got something greater. For what animal could suit this land better? A creature that stores its own water, walks on sand as if on carpet, and thrives where horses despair.","why":"A moment from How the Camels Came to the Desert"},"sl-fk.pabuji-camels":{"route":"#/story/fk.pabuji-camels","art":null,"cta":"Read the story","src":"story:fk.pabuji-camels:moral","title":"What How the Camels Came to the Desert says","body":"A promise to the smallest person weighs the same as any other — keep it like a hero.","why":"The story’s own lesson"},"sw-fk.pabuji-camels-0":{"route":"#/story/fk.pabuji-camels","art":null,"cta":"Read the story","src":"story:fk.pabuji-camels:words_hi:0","title":"A Hindi word from How the Camels Came to the Desert","text":"भेंट","roman":"bhent","lang":"hi","play":{"q":"What does it mean?","opts":["gift","land","thanks"],"a":0,"after":"भेंट (bhent) means “gift”."},"why":"A word from How the Camels Came to the Desert"},"sw-fk.pabuji-camels-1":{"route":"#/story/fk.pabuji-camels","art":null,"cta":"Read the story","src":"story:fk.pabuji-camels:words_hi:1","title":"A Hindi word from How the Camels Came to the Desert","text":"झुंड","roman":"jhund","lang":"hi","play":{"q":"What does it mean?","opts":["herd","letter","the future"],"a":0,"after":"झुंड (jhund) means “herd”."},"why":"A word from How the Camels Came to the Desert"},"sw-fk.pabuji-camels-2":{"route":"#/story/fk.pabuji-camels","art":null,"cta":"Read the story","src":"story:fk.pabuji-camels:words_hi:2","title":"A Hindi word from How the Camels Came to the Desert","text":"वीर","roman":"veer","lang":"hi","play":{"q":"What does it mean?","opts":["hero","letter","the future"],"a":0,"after":"वीर (veer) means “hero”."},"why":"A word from How the Camels Came to the Desert"},"sp-fk.pabuji-camels":{"route":"#/story/fk.pabuji-camels","art":null,"cta":"Read the story","src":"story:fk.pabuji-camels:place:0","title":"How the Camels Came to the Desert","play":{"q":"Which place on the map does this story light up?","opts":["Rajasthan","Bihar","Karnataka"],"a":0,"after":"It lights up Rajasthan."},"why":"A map question"},"st-fk.deshnoke-mice":{"route":"#/story/fk.deshnoke-mice","art":"art/story/fk-deshnoke-mice.jpg","cta":"Read the story","src":"story:fk.deshnoke-mice:scenes:0:text","title":"The Temple of the Small Ones","body":"In the town of Deshnoke, near Bikaner in the desert of Rajasthan, stands a temple with silver doors and marble lattices, built in honour of Karni Mata — a sainted woman of the Charan community who lived here six centuries ago, and whom her people revere as an embodiment of the Mother Goddess herself.","why":"From The Western Lands"},"sh-fk.deshnoke-mice":{"route":"#/story/fk.deshnoke-mice","art":null,"cta":"Read the story","src":"story:fk.deshnoke-mice:hook","title":"The Temple of the Small Ones","body":"In one Rajasthan temple, the most honoured worshippers run on four small feet — and everyone steps carefully, and everyone is glad.","why":"From The Western Lands"},"sm-fk.deshnoke-mice":{"route":"#/story/fk.deshnoke-mice","art":null,"cta":"Read the story","src":"story:fk.deshnoke-mice:scenes:4:text","title":"The Temple of the Small Ones — the middle","body":"Prasad is shared with the kaba as with honoured guests — grain and sweets and those great bowls of milk, ringed with small drinkers, tails hanging like fringe. Food a kaba has nibbled is counted blessed, not spoiled.","why":"A moment from The Temple of the Small Ones"},"sl-fk.deshnoke-mice":{"route":"#/story/fk.deshnoke-mice","art":null,"cta":"Read the story","src":"story:fk.deshnoke-mice:moral","title":"What The Temple of the Small Ones says","body":"Holiness can be small, quick and whiskered — a place is measured by how it treats its least.","why":"The story’s own lesson"},"sp-fk.deshnoke-mice":{"route":"#/story/fk.deshnoke-mice","art":null,"cta":"Read the story","src":"story:fk.deshnoke-mice:place:0","title":"The Temple of the Small Ones","play":{"q":"Which place on the map does this story light up?","opts":["Rajasthan","Gujarat","Madhya Pradesh"],"a":0,"after":"It lights up Rajasthan."},"why":"A map question"},"st-fk.chand-baori":{"route":"#/story/fk.chand-baori","art":"art/story/fk-chand-baori.jpg","cta":"Read the story","src":"story:fk.chand-baori:scenes:0:text","title":"The Well That Goes Down Like a Mountain Upside-Down","body":"In the village of Abhaneri, in eastern Rajasthan, there is a hole in the ground that stops people mid-sentence. Chand Baori: a stepwell — a well with stairs — but of such a size that the word hardly serves. Thirteen storeys deep.","why":"From The Western Lands"},"sh-fk.chand-baori":{"route":"#/story/fk.chand-baori","art":null,"cta":"Read the story","src":"story:fk.chand-baori:hook","title":"The Well That Goes Down Like a Mountain Upside-Down","body":"Three and a half thousand steps, thirteen floors deep, cut into the desert — and the village says it was built in a single night.","why":"From The Western Lands"},"sm-fk.chand-baori":{"route":"#/story/fk.chand-baori","art":null,"cta":"Read the story","src":"story:fk.chand-baori:scenes:4:text","title":"The Well That Goes Down Like a Mountain Upside-Down — the middle","body":"Why build such a thing at all? Because in the desert, water is not found — it is reached. The rains come briefly and sink deep, and the well's level falls and falls through the dry months.","why":"A moment from The Well That Goes Down Like a Mountain Upside-Down"},"sl-fk.chand-baori":{"route":"#/story/fk.chand-baori","art":null,"cta":"Read the story","src":"story:fk.chand-baori:moral","title":"What The Well That Goes Down Like a Mountain Upside-Down says","body":"In dry country, water is climbed for — and what a people treasures, they build beautifully.","why":"The story’s own lesson"},"sw-fk.chand-baori-0":{"route":"#/story/fk.chand-baori","art":null,"cta":"Read the story","src":"story:fk.chand-baori:words_hi:0","title":"A Hindi word from The Well That Goes Down Like a Mountain Upside-Down","text":"सीढ़ी","roman":"seedhi","lang":"hi","play":{"q":"What does it mean?","opts":["stair","mango","throne"],"a":0,"after":"सीढ़ी (seedhi) means “stair”."},"why":"A word from The Well That Goes Down Like a Mountain Upside-Down"},"sw-fk.chand-baori-2":{"route":"#/story/fk.chand-baori","art":null,"cta":"Read the story","src":"story:fk.chand-baori:words_hi:2","title":"A Hindi word from The Well That Goes Down Like a Mountain Upside-Down","text":"गहरा","roman":"gehra","lang":"hi","play":{"q":"What does it mean?","opts":["deep","mirror","to fill"],"a":0,"after":"गहरा (gehra) means “deep”."},"why":"A word from The Well That Goes Down Like a Mountain Upside-Down"},"sp-fk.chand-baori":{"route":"#/story/fk.chand-baori","art":null,"cta":"Read the story","src":"story:fk.chand-baori:place:0","title":"The Well That Goes Down Like a Mountain Upside-Down","play":{"q":"Which place on the map does this story light up?","opts":["Rajasthan","Ladakh","Telangana"],"a":0,"after":"It lights up Rajasthan."},"why":"A map question"},"st-fk.gond-mahua":{"route":"#/story/fk.gond-mahua","art":"art/story/fk-gond-mahua.jpg","cta":"Read the story","src":"story:fk.gond-mahua:scenes:0:text","title":"The Tree That Feeds Everyone","body":"Across the forest country of central India — the homeland of the Gond people, one of the largest Adivasi communities in the world — there grows a broad, generous tree called the mahua. And for the Gond and their neighbours, the mahua is not one tree among many.","why":"From The Heart of the Land"},"sh-fk.gond-mahua":{"route":"#/story/fk.gond-mahua","art":null,"cta":"Read the story","src":"story:fk.gond-mahua:hook","title":"The Tree That Feeds Everyone","body":"Before dawn, whole families walk out to the big trees and gather the night's fallen flowers — sweet enough to eat, bright enough to thank a god for.","why":"From The Heart of the Land"},"sm-fk.gond-mahua":{"route":"#/story/fk.gond-mahua","art":null,"cta":"Read the story","src":"story:fk.gond-mahua:scenes:4:text","title":"The Tree That Feeds Everyone — the middle","body":"And the family under the tree, in the Gond understanding, is bigger than the human one. The bears love mahua flowers famously — so do deer, wild pigs, birds, a whole forest of gatherers.","why":"A moment from The Tree That Feeds Everyone"},"sl-fk.gond-mahua":{"route":"#/story/fk.gond-mahua","art":null,"cta":"Read the story","src":"story:fk.gond-mahua:moral","title":"What The Tree That Feeds Everyone says","body":"Honour what feeds you by letting it stand — the best harvests are the given ones.","why":"The story’s own lesson"},"sp-fk.gond-mahua":{"route":"#/story/fk.gond-mahua","art":null,"cta":"Read the story","src":"story:fk.gond-mahua:place:0","title":"The Tree That Feeds Everyone","play":{"q":"Which place on the map does this story light up?","opts":["Madhya Pradesh","Odisha","Andhra Pradesh"],"a":0,"after":"It lights up Madhya Pradesh."},"why":"A map question"},"st-it.tansen-tigers":{"route":"#/story/it.tansen-tigers","art":"art/story/it-tansen-tigers.jpg","cta":"Read the story","src":"story:it.tansen-tigers:scenes:0:text","title":"The Boy Who Spoke Tiger","body":"Four and a half centuries ago, near Gwalior in what is now Madhya Pradesh, in a village called Behat, there lived a boy named Ramtanu. The world would come to know him by another name — Tansen, the greatest singer of his age.","why":"From The Heart of the Land"},"sh-it.tansen-tigers":{"route":"#/story/it.tansen-tigers","art":null,"cta":"Read the story","src":"story:it.tansen-tigers:hook","title":"The Boy Who Spoke Tiger","body":"Travellers on the forest road froze — a tiger's roar, close by. Then the tiger stepped out, laughing: a small boy, extremely pleased with himself.","why":"From The Heart of the Land"},"sm-it.tansen-tigers":{"route":"#/story/it.tansen-tigers","art":null,"cta":"Read the story","src":"story:it.tansen-tigers:scenes:4:text","title":"The Boy Who Spoke Tiger — the middle","body":"So Ramtanu went to study with Haridas — years of training the tradition places in Vrindavan — and the ear that had held tigers learnt to hold ragas. The boy who could become any sound grew into a man who could build any feeling out of sound, note by note.","why":"A moment from The Boy Who Spoke Tiger"},"sl-it.tansen-tigers":{"route":"#/story/it.tansen-tigers","art":null,"cta":"Read the story","src":"story:it.tansen-tigers:moral","title":"What The Boy Who Spoke Tiger says","body":"Great skill begins as great attention — listen to the world hard enough and one day it sings back through you.","why":"The story’s own lesson"},"sw-it.tansen-tigers-2":{"route":"#/story/it.tansen-tigers","art":null,"cta":"Read the story","src":"story:it.tansen-tigers:words_hi:2","title":"A Hindi word from The Boy Who Spoke Tiger","text":"गुरु","roman":"guru","lang":"hi","play":{"q":"What does it mean?","opts":["teacher","mud","tortoise"],"a":0,"after":"गुरु (guru) means “teacher”."},"why":"A word from The Boy Who Spoke Tiger"},"sp-it.tansen-tigers":{"route":"#/story/it.tansen-tigers","art":null,"cta":"Read the story","src":"story:it.tansen-tigers:place:0","title":"The Boy Who Spoke Tiger","play":{"q":"Which place on the map does this story light up?","opts":["Madhya Pradesh","Tripura","Delhi"],"a":0,"after":"It lights up Madhya Pradesh."},"why":"A map question"},"st-it.teejan-pandavani":{"route":"#/story/it.teejan-pandavani","art":"art/story/it-teejan-pandavani.jpg","cta":"Read the story","src":"story:it.teejan-pandavani:scenes:0:text","title":"The Girl Who Sang the Mahabharata","body":"Chhattisgarh has its own way with the Mahabharata, and it is like nothing else in India. It is called Pandavani — the songs of the Pandavas.","why":"From The Heart of the Land"},"sh-it.teejan-pandavani":{"route":"#/story/it.teejan-pandavani","art":null,"cta":"Read the story","src":"story:it.teejan-pandavani:hook","title":"The Girl Who Sang the Mahabharata","body":"In Chhattisgarh the great epic is not read aloud — it is SUNG, by one performer who becomes the whole battlefield. And the greatest of them started as a girl listening at her grandfather's knee.","why":"From The Heart of the Land"},"sm-it.teejan-pandavani":{"route":"#/story/it.teejan-pandavani","art":null,"cta":"Read the story","src":"story:it.teejan-pandavani:scenes:4:text","title":"The Girl Who Sang the Mahabharata — the middle","body":"What audiences saw, once they saw her, ended the argument. Teejan Bai in full flight is the epic weather-fronted into one person: voice like a festival drum, the tambura flashing from bow to mace, Draupadi's fury and Bhima's laughter pouring out of the same throat.","why":"A moment from The Girl Who Sang the Mahabharata"},"sl-it.teejan-pandavani":{"route":"#/story/it.teejan-pandavani","art":null,"cta":"Read the story","src":"story:it.teejan-pandavani:moral","title":"What The Girl Who Sang the Mahabharata says","body":"An old story stays alive by finding new voices — even when the new voice has to fight to stand.","why":"The story’s own lesson"},"sw-it.teejan-pandavani-0":{"route":"#/story/it.teejan-pandavani","art":null,"cta":"Read the story","src":"story:it.teejan-pandavani:words_hi:0","title":"A Hindi word from The Girl Who Sang the Mahabharata","text":"गायन","roman":"gaayan","lang":"hi","play":{"q":"What does it mean?","opts":["singing","moonlight","to stop"],"a":0,"after":"गायन (gaayan) means “singing”."},"why":"A word from The Girl Who Sang the Mahabharata"},"sw-it.teejan-pandavani-1":{"route":"#/story/it.teejan-pandavani","art":null,"cta":"Read the story","src":"story:it.teejan-pandavani:words_hi:1","title":"A Hindi word from The Girl Who Sang the Mahabharata","text":"वीणा","roman":"veena","lang":"hi","play":{"q":"What does it mean?","opts":["a stringed instrument","nail","train"],"a":0,"after":"वीणा (veena) means “a stringed instrument”."},"why":"A word from The Girl Who Sang the Mahabharata"},"sw-it.teejan-pandavani-2":{"route":"#/story/it.teejan-pandavani","art":null,"cta":"Read the story","src":"story:it.teejan-pandavani:words_hi:2","title":"A Hindi word from The Girl Who Sang the Mahabharata","text":"मंच","roman":"manch","lang":"hi","play":{"q":"What does it mean?","opts":["stage","mud","tortoise"],"a":0,"after":"मंच (manch) means “stage”."},"why":"A word from The Girl Who Sang the Mahabharata"},"sp-it.teejan-pandavani":{"route":"#/story/it.teejan-pandavani","art":null,"cta":"Read the story","src":"story:it.teejan-pandavani:place:0","title":"The Girl Who Sang the Mahabharata","play":{"q":"Which place on the map does this story light up?","opts":["Chhattisgarh","Assam","Karnataka"],"a":0,"after":"It lights up Chhattisgarh."},"why":"A map question"},"st-fk.ghotul-lamps":{"route":"#/story/fk.ghotul-lamps","art":"art/story/fk-ghotul-lamps.jpg","cta":"Read the story","src":"story:fk.ghotul-lamps:scenes:0:text","title":"The Children's Own House","body":"In the forest country of Bastar, in southern Chhattisgarh, the Muria people have long kept an institution that visitors from everywhere find astonishing. In the village stands a spacious house — often the finest-kept in the village — that belongs to no family at all.","why":"From The Heart of the Land"},"sh-fk.ghotul-lamps":{"route":"#/story/fk.ghotul-lamps","art":null,"cta":"Read the story","src":"story:fk.ghotul-lamps:hook","title":"The Children's Own House","body":"In some Bastar villages there is a big house that belongs to no family — because it belongs to the village's young people, who run it themselves.","why":"From The Heart of the Land"},"sm-fk.ghotul-lamps":{"route":"#/story/fk.ghotul-lamps","art":null,"cta":"Read the story","src":"story:fk.ghotul-lamps:scenes:4:text","title":"The Children's Own House — the middle","body":"The evenings themselves are the treasure: songs learned and taught, the great story-hoard of the Muria passed down, dances rehearsed for the festivals — for it is the ghotul members who drum and dance at the village's great occasions, and their performances are the village's pride.","why":"A moment from The Children's Own House"},"sl-fk.ghotul-lamps":{"route":"#/story/fk.ghotul-lamps","art":null,"cta":"Read the story","src":"story:fk.ghotul-lamps:moral","title":"What The Children's Own House says","body":"Trust the young with something real, and they will practise their way into carrying it.","why":"The story’s own lesson"},"sw-fk.ghotul-lamps-1":{"route":"#/story/fk.ghotul-lamps","art":null,"cta":"Read the story","src":"story:fk.ghotul-lamps:words_hi:1","title":"A Hindi word from The Children's Own House","text":"नियम","roman":"niyam","lang":"hi","play":{"q":"What does it mean?","opts":["rule","neighbour","truth"],"a":0,"after":"नियम (niyam) means “rule”."},"why":"A word from The Children's Own House"},"sw-fk.ghotul-lamps-2":{"route":"#/story/fk.ghotul-lamps","art":null,"cta":"Read the story","src":"story:fk.ghotul-lamps:words_hi:2","title":"A Hindi word from The Children's Own House","text":"ज़िम्मेदारी","roman":"zimmedari","lang":"hi","play":{"q":"What does it mean?","opts":["responsibility","repair","a circle"],"a":0,"after":"ज़िम्मेदारी (zimmedari) means “responsibility”."},"why":"A word from The Children's Own House"},"sp-fk.ghotul-lamps":{"route":"#/story/fk.ghotul-lamps","art":null,"cta":"Read the story","src":"story:fk.ghotul-lamps:place:0","title":"The Children's Own House","play":{"q":"Which place on the map does this story light up?","opts":["Chhattisgarh","Gujarat","Madhya Pradesh"],"a":0,"after":"It lights up Chhattisgarh."},"why":"A map question"},"st-fk.bastar-chariot":{"route":"#/story/fk.bastar-chariot","art":"art/story/fk-bastar-chariot.jpg","cta":"Read the story","src":"story:fk.bastar-chariot:scenes:0:text","title":"The Chariot the Whole Forest Pulls","body":"In Jagdalpur, the old capital of Bastar in Chhattisgarh, they keep a Dussehra unlike any other in India — and they keep it longer than anyone keeps anything.","why":"From The Heart of the Land"},"sh-fk.bastar-chariot":{"route":"#/story/fk.bastar-chariot","art":null,"cta":"Read the story","src":"story:fk.bastar-chariot:hook","title":"The Chariot the Whole Forest Pulls","body":"The world's longest festival runs for some seventy-five days — and at its heart, hundreds of hands haul a giant wooden chariot built new every single year.","why":"From The Heart of the Land"},"sm-fk.bastar-chariot":{"route":"#/story/fk.bastar-chariot","art":null,"cta":"Read the story","src":"story:fk.bastar-chariot:scenes:4:text","title":"The Chariot the Whole Forest Pulls — the middle","body":"For days the great wheels groan around the streets of Jagdalpur, the ropes taut with hauliers, the crowds vast, the air full of drums.","why":"A moment from The Chariot the Whole Forest Pulls"},"sl-fk.bastar-chariot":{"route":"#/story/fk.bastar-chariot","art":null,"cta":"Read the story","src":"story:fk.bastar-chariot:moral","title":"What The Chariot the Whole Forest Pulls says","body":"The doing together is the celebration — share out the work and the festival builds itself.","why":"The story’s own lesson"},"sp-fk.bastar-chariot":{"route":"#/story/fk.bastar-chariot","art":null,"cta":"Read the story","src":"story:fk.bastar-chariot:place:0","title":"The Chariot the Whole Forest Pulls","play":{"q":"Which place on the map does this story light up?","opts":["Chhattisgarh","Ladakh","Sikkim"],"a":0,"after":"It lights up Chhattisgarh."},"why":"A map question"},"st-fk.myna-judge":{"route":"#/story/fk.myna-judge","art":"art/story/fk-myna-judge.jpg","cta":"Read the story","src":"story:fk.myna-judge:scenes:0:text","title":"The Myna Who Judged the Quarrel","body":"In the forests of Bastar, in Chhattisgarh, lives a glossy black bird with bright yellow wattles called the hill myna — and she has one famous gift. She can repeat, perfectly, any voice she hears. Chhattisgarh loves her so well it made her the state bird.","why":"From The Heart of the Land"},"sh-fk.myna-judge":{"route":"#/story/fk.myna-judge","art":null,"cta":"Read the story","src":"story:fk.myna-judge:hook","title":"The Myna Who Judged the Quarrel","body":"Two loud neighbours, one disputed mango tree, and a judge with feathers who says nothing of her own — she only repeats.","why":"From The Heart of the Land"},"sm-fk.myna-judge":{"route":"#/story/fk.myna-judge","art":null,"cta":"Read the story","src":"story:fk.myna-judge:scenes:4:text","title":"The Myna Who Judged the Quarrel — the middle","body":"The first neighbour gave his speech, all grievance and thunder. The myna cocked her head and gave it back to him — every word, every snort, the exact curl of \"and THAT man calls himself a neighbour!\" He stood there hearing himself, and his ears slowly went red.","why":"A moment from The Myna Who Judged the Quarrel"},"sl-fk.myna-judge":{"route":"#/story/fk.myna-judge","art":null,"cta":"Read the story","src":"story:fk.myna-judge:moral","title":"What The Myna Who Judged the Quarrel says","body":"Hear yourself as others hear you, and half the quarrel settles itself.","why":"The story’s own lesson"},"sw-fk.myna-judge-1":{"route":"#/story/fk.myna-judge","art":null,"cta":"Read the story","src":"story:fk.myna-judge:words_hi:1","title":"A Hindi word from The Myna Who Judged the Quarrel","text":"मैना","roman":"maina","lang":"hi","play":{"q":"What does it mean?","opts":["myna bird","ox, bullock","wall"],"a":0,"after":"मैना (maina) means “myna bird”."},"why":"A word from The Myna Who Judged the Quarrel"},"sp-fk.myna-judge":{"route":"#/story/fk.myna-judge","art":null,"cta":"Read the story","src":"story:fk.myna-judge:place:0","title":"The Myna Who Judged the Quarrel","play":{"q":"Which place on the map does this story light up?","opts":["Chhattisgarh","Nagaland","Andaman & Nicobar Islands"],"a":0,"after":"It lights up Chhattisgarh."},"why":"A map question"},"st-fk.agaria-first-fire":{"route":"#/story/fk.agaria-first-fire","art":"art/story/fk-agaria-first-fire.jpg","cta":"Read the story","src":"story:fk.agaria-first-fire:scenes:0:text","title":"The People of the First Furnace","body":"Across the hill country of Chhattisgarh and central India live the Agaria — a community whose very name carries fire in it, for ag is fire in their tongue as in many.","why":"From The Heart of the Land"},"sh-fk.agaria-first-fire":{"route":"#/story/fk.agaria-first-fire","art":null,"cta":"Read the story","src":"story:fk.agaria-first-fire:hook","title":"The People of the First Furnace","body":"Before the tools, before the ploughs, someone had to be first to coax metal out of stone — and their descendants still greet the fire politely.","why":"From The Heart of the Land"},"sm-fk.agaria-first-fire":{"route":"#/story/fk.agaria-first-fire","art":null,"cta":"Read the story","src":"story:fk.agaria-first-fire:scenes:4:text","title":"The People of the First Furnace — the middle","body":"And think what that agreement gave everyone else. The farmer's ploughshare, the axe, the sickle, the arrowhead, the cooking pot's stand — for centuries, the villages of central India ran on Agaria iron.","why":"A moment from The People of the First Furnace"},"sl-fk.agaria-first-fire":{"route":"#/story/fk.agaria-first-fire","art":null,"cta":"Read the story","src":"story:fk.agaria-first-fire:moral","title":"What The People of the First Furnace says","body":"Every craft began as a friendship with something wild — honour the agreement and it holds.","why":"The story’s own lesson"},"sp-fk.agaria-first-fire":{"route":"#/story/fk.agaria-first-fire","art":null,"cta":"Read the story","src":"story:fk.agaria-first-fire:place:0","title":"The People of the First Furnace","play":{"q":"Which place on the map does this story light up?","opts":["Chhattisgarh","Tamil Nadu","Delhi"],"a":0,"after":"It lights up Chhattisgarh."},"why":"A map question"},"st-fk.chitrakote-sings":{"route":"#/story/fk.chitrakote-sings","art":"art/story/fk-chitrakote-sings.jpg","cta":"Read the story","src":"story:fk.chitrakote-sings:scenes:0:text","title":"The Waterfall That Sings","body":"In Bastar, in Chhattisgarh, the Indravati river comes to a horseshoe-shaped cliff and steps off it, all at once, in a curtain of falling water so wide that people call Chitrakote the widest waterfall in India — the country's own little Niagara, wearing a permanent scarf of mist.","why":"From The Heart of the Land"},"sh-fk.chitrakote-sings":{"route":"#/story/fk.chitrakote-sings","art":null,"cta":"Read the story","src":"story:fk.chitrakote-sings:hook","title":"The Waterfall That Sings","body":"In the rains it roars like a crowd; in winter it plays like a flute. The people who live beside it say the river is practising.","why":"From The Heart of the Land"},"sm-fk.chitrakote-sings":{"route":"#/story/fk.chitrakote-sings","art":null,"cta":"Read the story","src":"story:fk.chitrakote-sings:scenes:4:text","title":"The Waterfall That Sings — the middle","body":"\"People are the same,\" the old man added, since a grandfather never wastes a waterfall. \"Loud seasons, soft seasons, full years and lean ones — and the same person underneath all of it. Do not mistake somebody's quiet month for their whole music.\"","why":"A moment from The Waterfall That Sings"},"sl-fk.chitrakote-sings":{"route":"#/story/fk.chitrakote-sings","art":null,"cta":"Read the story","src":"story:fk.chitrakote-sings:moral","title":"What The Waterfall That Sings says","body":"The same heart sings differently by season — judge no one by a single month's song.","why":"The story’s own lesson"},"sp-fk.chitrakote-sings":{"route":"#/story/fk.chitrakote-sings","art":null,"cta":"Read the story","src":"story:fk.chitrakote-sings:place:0","title":"The Waterfall That Sings","play":{"q":"Which place on the map does this story light up?","opts":["Chhattisgarh","Arunachal Pradesh","Jammu & Kashmir"],"a":0,"after":"It lights up Chhattisgarh."},"why":"A map question"},"st-fk.danteshwari-bastar":{"route":"#/story/fk.danteshwari-bastar","art":"art/story/fk-danteshwari-bastar.jpg","cta":"Read the story","src":"story:fk.danteshwari-bastar:scenes:0:text","title":"The Goddess Who Walked Behind","body":"Bastar, the great forest land of southern Chhattisgarh, has a mother: Danteshwari. Every community of the region — village and town, forest and field — honours her as the land's own goddess, and her chief temple stands at Dantewada, where two rivers meet.","why":"From The Heart of the Land"},"sh-fk.danteshwari-bastar":{"route":"#/story/fk.danteshwari-bastar","art":null,"cta":"Read the story","src":"story:fk.danteshwari-bastar:hook","title":"The Goddess Who Walked Behind","body":"The goddess made the king one promise: I will follow you into the new land — walk ahead, listen for my anklets, and do not look back.","why":"From The Heart of the Land"},"sm-fk.danteshwari-bastar":{"route":"#/story/fk.danteshwari-bastar","art":null,"cta":"Read the story","src":"story:fk.danteshwari-bastar:scenes:4:text","title":"The Goddess Who Walked Behind — the middle","body":"The condition was broken, and the goddess stayed where his glance had found her. \"This far I have walked,\" she said, \"and this far is enough. Here, where the rivers meet, I remain — and from here I will hold your whole land.\" There was no anger in it, the tellers insist.","why":"A moment from The Goddess Who Walked Behind"},"sl-fk.danteshwari-bastar":{"route":"#/story/fk.danteshwari-bastar","art":null,"cta":"Read the story","src":"story:fk.danteshwari-bastar:moral","title":"What The Goddess Who Walked Behind says","body":"Some promises ask you to walk on trust — and even a stumble can end in a blessing, where there is love.","why":"The story’s own lesson"},"sw-fk.danteshwari-bastar-1":{"route":"#/story/fk.danteshwari-bastar","art":null,"cta":"Read the story","src":"story:fk.danteshwari-bastar:words_hi:1","title":"A Hindi word from The Goddess Who Walked Behind","text":"पायल","roman":"paayal","lang":"hi","play":{"q":"What does it mean?","opts":["anklets","poor","wit"],"a":0,"after":"पायल (paayal) means “anklets”."},"why":"A word from The Goddess Who Walked Behind"},"sp-fk.danteshwari-bastar":{"route":"#/story/fk.danteshwari-bastar","art":null,"cta":"Read the story","src":"story:fk.danteshwari-bastar:place:0","title":"The Goddess Who Walked Behind","play":{"q":"Which place on the map does this story light up?","opts":["Chhattisgarh","Goa","Manipur"],"a":0,"after":"It lights up Chhattisgarh."},"why":"A map question"},"st-fk.tejimola":{"route":"#/story/fk.tejimola","art":"art/story/fk-tejimola.jpg","cta":"Read the story","src":"story:fk.tejimola:scenes:0:text","title":"Tejimola, Who Kept Becoming","body":"In Assam, on the bank of the great river, lived a merchant and his daughter Tejimola. Her mother was gone, and her father loved her the way you hold the last ember on a cold night. She sang while she worked — everyone on that bank knew her voice before they knew her face.","why":"From The Eastern Hills"},"sh-fk.tejimola":{"route":"#/story/fk.tejimola","art":null,"cta":"Read the story","src":"story:fk.tejimola:hook","title":"Tejimola, Who Kept Becoming","body":"They tried to make her gone. She came back as a vine, then a tree, then a lotus — and she never once stopped singing.","why":"From The Eastern Hills"},"sm-fk.tejimola":{"route":"#/story/fk.tejimola","art":null,"cta":"Read the story","src":"story:fk.tejimola:scenes:5:text","title":"Tejimola, Who Kept Becoming — the middle","body":"So the tree was cut and thrown in the river. And the river — which had carried her father away and would carry him home — took the wood under, and where it touched the water, a lotus opened. One lotus, in midstream, where no lotus grows.","why":"A moment from Tejimola, Who Kept Becoming"},"sl-fk.tejimola":{"route":"#/story/fk.tejimola","art":null,"cta":"Read the story","src":"story:fk.tejimola:moral","title":"What Tejimola, Who Kept Becoming says","body":"Love keeps becoming. You cannot pull it up, cut it down, or float it away.","why":"The story’s own lesson"},"sw-fk.tejimola-1":{"route":"#/story/fk.tejimola","art":null,"cta":"Read the story","src":"story:fk.tejimola:words_hi:1","title":"A Hindi word from Tejimola, Who Kept Becoming","text":"कमल","roman":"kamal","lang":"hi","play":{"q":"What does it mean?","opts":["lotus","poor","wit"],"a":0,"after":"कमल (kamal) means “lotus”."},"why":"A word from Tejimola, Who Kept Becoming"},"sp-fk.tejimola":{"route":"#/story/fk.tejimola","art":null,"cta":"Read the story","src":"story:fk.tejimola:place:0","title":"Tejimola, Who Kept Becoming","play":{"q":"Which place on the map does this story light up?","opts":["Assam","Kerala","Rajasthan"],"a":0,"after":"It lights up Assam."},"why":"A map question"},"st-fk.bordoisila":{"route":"#/story/fk.bordoisila","art":"art/story/fk-bordoisila.jpg","cta":"Read the story","src":"story:fk.bordoisila:scenes:0:text","title":"The Wind Who Runs Home to Her Mother","body":"At the very end of the cold season in Assam, when the mango trees are in flower, there always comes an evening when the wind gets up all at once — banging doors, rolling pots off verandas, sending everyone running for the washing.","why":"From The Eastern Hills"},"sh-fk.bordoisila":{"route":"#/story/fk.bordoisila","art":null,"cta":"Read the story","src":"story:fk.bordoisila:hook","title":"The Wind Who Runs Home to Her Mother","body":"Every spring, just before Bihu, a wild wind bangs through Assam. It is not a storm. It is a daughter, running.","why":"From The Eastern Hills"},"sm-fk.bordoisila":{"route":"#/story/fk.bordoisila","art":null,"cta":"Read the story","src":"story:fk.bordoisila:scenes:4:text","title":"The Wind Who Runs Home to Her Mother — the middle","body":"Then come the Bihu days themselves, and the weather goes gentle — because Bordoisila is home, sitting with her mother, being fed, telling everything, and the whole sky settles the way a house settles when the daughter is back in it.","why":"A moment from The Wind Who Runs Home to Her Mother"},"sl-fk.bordoisila":{"route":"#/story/fk.bordoisila","art":null,"cta":"Read the story","src":"story:fk.bordoisila:moral","title":"What The Wind Who Runs Home to Her Mother says","body":"Joy runs and grief walks, and both of them are wind.","why":"The story’s own lesson"},"sw-fk.bordoisila-0":{"route":"#/story/fk.bordoisila","art":null,"cta":"Read the story","src":"story:fk.bordoisila:words_hi:0","title":"A Hindi word from The Wind Who Runs Home to Her Mother","text":"आँधी","roman":"aandhi","lang":"hi","play":{"q":"What does it mean?","opts":["storm wind","promise","word given"],"a":0,"after":"आँधी (aandhi) means “storm wind”."},"why":"A word from The Wind Who Runs Home to Her Mother"},"sp-fk.bordoisila":{"route":"#/story/fk.bordoisila","art":null,"cta":"Read the story","src":"story:fk.bordoisila:place:0","title":"The Wind Who Runs Home to Her Mother","play":{"q":"Which place on the map does this story light up?","opts":["Assam","Mizoram","West Bengal"],"a":0,"after":"It lights up Assam."},"why":"A map question"},"st-fk.xorai-elephant":{"route":"#/story/fk.xorai-elephant","art":"art/story/fk-xorai-elephant.jpg","cta":"Read the story","src":"story:fk.xorai-elephant:scenes:0:text","title":"The Sparrow, the Frog, and the Very Big Elephant","body":"In an Assamese forest, in a simolu tree — the silk-cotton, the one that flowers red before it leafs — a pair of sparrows built a nest, and there were eggs in it, and the two of them took turns keeping the eggs warm and telling each other how clever they had been about the location.","why":"From The Eastern Hills"},"sh-fk.xorai-elephant":{"route":"#/story/fk.xorai-elephant","art":null,"cta":"Read the story","src":"story:fk.xorai-elephant:hook","title":"The Sparrow, the Frog, and the Very Big Elephant","body":"He was the biggest thing in the forest and he never once looked where he was going. The smallest things in the forest decided to teach him.","why":"From The Eastern Hills"},"sm-fk.xorai-elephant":{"route":"#/story/fk.xorai-elephant","art":null,"cta":"Read the story","src":"story:fk.xorai-elephant:scenes:4:text","title":"The Sparrow, the Frog, and the Very Big Elephant — the middle","body":"The frog's plan needed nobody to be strong. At noon, the bee hummed her softest song round the elephant's ears until his eyes went heavy and he forgot to think.","why":"A moment from The Sparrow, the Frog, and the Very Big Elephant"},"sl-fk.xorai-elephant":{"route":"#/story/fk.xorai-elephant","art":null,"cta":"Read the story","src":"story:fk.xorai-elephant:moral","title":"What The Sparrow, the Frog, and the Very Big Elephant says","body":"Being big is not a licence, being small is not helpless — and a sorry only counts when your feet change.","why":"The story’s own lesson"},"sw-fk.xorai-elephant-1":{"route":"#/story/fk.xorai-elephant","art":null,"cta":"Read the story","src":"story:fk.xorai-elephant:words_hi:1","title":"A Hindi word from The Sparrow, the Frog, and the Very Big Elephant","text":"कीचड़","roman":"keechad","lang":"hi","play":{"q":"What does it mean?","opts":["mud","rise","a fire ceremony"],"a":0,"after":"कीचड़ (keechad) means “mud”."},"why":"A word from The Sparrow, the Frog, and the Very Big Elephant"},"sw-fk.xorai-elephant-2":{"route":"#/story/fk.xorai-elephant","art":null,"cta":"Read the story","src":"story:fk.xorai-elephant:words_hi:2","title":"A Hindi word from The Sparrow, the Frog, and the Very Big Elephant","text":"माफ़ी","roman":"maafi","lang":"hi","play":{"q":"What does it mean?","opts":["a sorry","root","a hand"],"a":0,"after":"माफ़ी (maafi) means “a sorry”."},"why":"A word from The Sparrow, the Frog, and the Very Big Elephant"},"sp-fk.xorai-elephant":{"route":"#/story/fk.xorai-elephant","art":null,"cta":"Read the story","src":"story:fk.xorai-elephant:place:0","title":"The Sparrow, the Frog, and the Very Big Elephant","play":{"q":"Which place on the map does this story light up?","opts":["Assam","Telangana","Daman & Diu"],"a":0,"after":"It lights up Assam."},"why":"A map question"},"st-fk.burhi-aair-sadhu":{"route":"#/story/fk.burhi-aair-sadhu","art":"art/story/fk-burhi-aair-sadhu.jpg","cta":"Read the story","src":"story:fk.burhi-aair-sadhu:scenes:0:text","title":"The Grandmother's Stories, Written Down","body":"For as long as anybody can count, the stories of Assam lived in one place: the evening.","why":"From The Eastern Hills"},"sh-fk.burhi-aair-sadhu":{"route":"#/story/fk.burhi-aair-sadhu","art":null,"cta":"Read the story","src":"story:fk.burhi-aair-sadhu:hook","title":"The Grandmother's Stories, Written Down","body":"The stories lived in evening voices, and evening voices do not last. One man decided the stories would.","why":"From The Eastern Hills"},"sm-fk.burhi-aair-sadhu":{"route":"#/story/fk.burhi-aair-sadhu","art":null,"cta":"Read the story","src":"story:fk.burhi-aair-sadhu:scenes:4:text","title":"The Grandmother's Stories, Written Down — the middle","body":"He called the book Burhi Aair Sadhu — the Old Mother's Stories. Sadhu is the Assamese word for a folk tale; a sadhu-kotha is what a grandmother says when the lamp is lit. He did not put his own cleverness on top of the tales.","why":"A moment from The Grandmother's Stories, Written Down"},"sl-fk.burhi-aair-sadhu":{"route":"#/story/fk.burhi-aair-sadhu","art":null,"cta":"Read the story","src":"story:fk.burhi-aair-sadhu:moral","title":"What The Grandmother's Stories, Written Down says","body":"Write down what your grandmother tells you, the way she tells it. One notebook can carry a thousand evenings.","why":"The story’s own lesson"},"sp-fk.burhi-aair-sadhu":{"route":"#/story/fk.burhi-aair-sadhu","art":null,"cta":"Read the story","src":"story:fk.burhi-aair-sadhu:place:0","title":"The Grandmother's Stories, Written Down","play":{"q":"Which place on the map does this story light up?","opts":["Assam","Andhra Pradesh","Jharkhand"],"a":0,"after":"It lights up Assam."},"why":"A map question"},"st-fk.bihu-goru":{"route":"#/story/fk.bihu-goru","art":"art/story/fk-bihu-goru.jpg","cta":"Read the story","src":"story:fk.bihu-goru:scenes:0:text","title":"The Morning the Cows Go First","body":"In the middle of April, when the first storms have washed the dust off the world, Assam begins its year — Bohag Bihu, the Rongali Bihu, the one made of dancing. And the very first morning of it does not belong to the people at all.","why":"From The Eastern Hills"},"sh-fk.bihu-goru":{"route":"#/story/fk.bihu-goru","art":null,"cta":"Read the story","src":"story:fk.bihu-goru:hook","title":"The Morning the Cows Go First","body":"The Assamese new year begins with a bath — and not for the people.","why":"From The Eastern Hills"},"sm-fk.bihu-goru":{"route":"#/story/fk.bihu-goru","art":null,"cta":"Read the story","src":"story:fk.bihu-goru:scenes:4:text","title":"The Morning the Cows Go First — the middle","body":"The boy asks the obvious thing: it is our new year — why do the cows go first?","why":"A moment from The Morning the Cows Go First"},"sl-fk.bihu-goru":{"route":"#/story/fk.bihu-goru","art":null,"cta":"Read the story","src":"story:fk.bihu-goru:moral","title":"What The Morning the Cows Go First says","body":"Begin the year by thanking whoever carried the last one.","why":"The story’s own lesson"},"sp-fk.bihu-goru":{"route":"#/story/fk.bihu-goru","art":null,"cta":"Read the story","src":"story:fk.bihu-goru:place:0","title":"The Morning the Cows Go First","play":{"q":"Which place on the map does this story light up?","opts":["Assam","Dadra & Nagar Haveli","Meghalaya"],"a":0,"after":"It lights up Assam."},"why":"A map question"},"st-fk.ali-aye-ligang":{"route":"#/story/fk.ali-aye-ligang","art":"art/story/fk-ali-aye-ligang.jpg","cta":"Read the story","src":"story:fk.ali-aye-ligang:scenes:0:text","title":"The Day the Sowing Begins","body":"Along the Brahmaputra live the Mising people — river people, whose houses stand on stilts, the chang ghar, with the flood water allowed to pass underneath like a guest using the corridor.","why":"From The Eastern Hills"},"sh-fk.ali-aye-ligang":{"route":"#/story/fk.ali-aye-ligang","art":null,"cta":"Read the story","src":"story:fk.ali-aye-ligang:hook","title":"The Day the Sowing Begins","body":"Before a single seed goes into the ground, the whole village has to dance about it. There is a reason.","why":"From The Eastern Hills"},"sm-fk.ali-aye-ligang":{"route":"#/story/fk.ali-aye-ligang","art":null,"cta":"Read the story","src":"story:fk.ali-aye-ligang:scenes:4:text","title":"The Day the Sowing Begins — the middle","body":"And for those few days, many families put the tools down entirely. No ploughing, no cutting, no felling. The earth is about to work for you all year; on her festival, she is the guest of honour.","why":"A moment from The Day the Sowing Begins"},"sl-fk.ali-aye-ligang":{"route":"#/story/fk.ali-aye-ligang","art":null,"cta":"Read the story","src":"story:fk.ali-aye-ligang:moral","title":"What The Day the Sowing Begins says","body":"Begin together, begin with thanks, and the year knows where to go.","why":"The story’s own lesson"},"sp-fk.ali-aye-ligang":{"route":"#/story/fk.ali-aye-ligang","art":null,"cta":"Read the story","src":"story:fk.ali-aye-ligang:place:0","title":"The Day the Sowing Begins","play":{"q":"Which place on the map does this story light up?","opts":["Assam","Karnataka","Puducherry"],"a":0,"after":"It lights up Assam."},"why":"A map question"},"st-fk.bwisagu":{"route":"#/story/fk.bwisagu","art":"art/story/fk-bwisagu.jpg","cta":"Read the story","src":"story:fk.bwisagu:scenes:0:text","title":"Bwisagu and the Butterfly Dance","body":"Assam is not one people, and mid-April proves it beautifully.","why":"From The Eastern Hills"},"sh-fk.bwisagu":{"route":"#/story/fk.bwisagu","art":null,"cta":"Read the story","src":"story:fk.bwisagu:hook","title":"Bwisagu and the Butterfly Dance","body":"Same April, same rivers, different drums — the Bodo new year has a dance that copies a butterfly.","why":"From The Eastern Hills"},"sm-fk.bwisagu":{"route":"#/story/fk.bwisagu","art":null,"cta":"Read the story","src":"story:fk.bwisagu:scenes:4:text","title":"Bwisagu and the Butterfly Dance — the middle","body":"The dance is the Bagurumba, and people call it the butterfly dance — arms wide, wrists turning, the whole line tilting and settling the way a butterfly does when it cannot decide between two flowers.","why":"A moment from Bwisagu and the Butterfly Dance"},"sl-fk.bwisagu":{"route":"#/story/fk.bwisagu","art":null,"cta":"Read the story","src":"story:fk.bwisagu:moral","title":"What Bwisagu and the Butterfly Dance says","body":"Neighbours do not need to be the same to be wise in the same direction.","why":"The story’s own lesson"},"sw-fk.bwisagu-0":{"route":"#/story/fk.bwisagu","art":null,"cta":"Read the story","src":"story:fk.bwisagu:words_hi:0","title":"A Hindi word from Bwisagu and the Butterfly Dance","text":"नया","roman":"naya","lang":"hi","play":{"q":"What does it mean?","opts":["new","root","a hand"],"a":0,"after":"नया (naya) means “new”."},"why":"A word from Bwisagu and the Butterfly Dance"},"sw-fk.bwisagu-2":{"route":"#/story/fk.bwisagu","art":null,"cta":"Read the story","src":"story:fk.bwisagu:words_hi:2","title":"A Hindi word from Bwisagu and the Butterfly Dance","text":"बाँसुरी","roman":"baansuri","lang":"hi","play":{"q":"What does it mean?","opts":["flute","smell","assembly"],"a":0,"after":"बाँसुरी (baansuri) means “flute”."},"why":"A word from Bwisagu and the Butterfly Dance"},"sp-fk.bwisagu":{"route":"#/story/fk.bwisagu","art":null,"cta":"Read the story","src":"story:fk.bwisagu:place:0","title":"Bwisagu and the Butterfly Dance","play":{"q":"Which place on the map does this story light up?","opts":["Assam","Madhya Pradesh","Uttar Pradesh"],"a":0,"after":"It lights up Assam."},"why":"A map question"},"st-fk.sohpetbneng":{"route":"#/story/fk.sohpetbneng","art":"art/story/fk-sohpetbneng.jpg","cta":"Read the story","src":"story:fk.sohpetbneng:scenes:0:text","title":"The Navel of the Sky","body":"In the Khasi hills of Meghalaya there is a hill called U Lum Sohpetbneng. Take the name apart the way a Khasi grandmother would: lum is hill, sohpet is navel, bneng is the sky.","why":"From The Eastern Hills"},"sh-fk.sohpetbneng":{"route":"#/story/fk.sohpetbneng","art":null,"cta":"Read the story","src":"story:fk.sohpetbneng:hook","title":"The Navel of the Sky","body":"There was once a ladder between heaven and earth, and it stood on a hill you can still climb.","why":"From The Eastern Hills"},"sm-fk.sohpetbneng":{"route":"#/story/fk.sohpetbneng","art":null,"cta":"Read the story","src":"story:fk.sohpetbneng:scenes:4:text","title":"The Navel of the Sky — the middle","body":"Seven families came down to stay. The Khasi remember them as the Hynñiew Trep — the Seven Huts — and when a Khasi elder says \"we are the children of the Seven Huts,\" this is the morning they mean. Nine families stayed above. Seven took the earth in trust.","why":"A moment from The Navel of the Sky"},"sl-fk.sohpetbneng":{"route":"#/story/fk.sohpetbneng","art":null,"cta":"Read the story","src":"story:fk.sohpetbneng:moral","title":"What The Navel of the Sky says","body":"You can lose the ladder and keep the sky. That is what remembering is for.","why":"The story’s own lesson"},"sw-fk.sohpetbneng-2":{"route":"#/story/fk.sohpetbneng","art":null,"cta":"Read the story","src":"story:fk.sohpetbneng:words_hi:2","title":"A Hindi word from The Navel of the Sky","text":"सात","roman":"saat","lang":"hi","play":{"q":"What does it mean?","opts":["seven","settlement","a vow"],"a":0,"after":"सात (saat) means “seven”."},"why":"A word from The Navel of the Sky"},"sp-fk.sohpetbneng":{"route":"#/story/fk.sohpetbneng","art":null,"cta":"Read the story","src":"story:fk.sohpetbneng:place:0","title":"The Navel of the Sky","play":{"q":"Which place on the map does this story light up?","opts":["Meghalaya","Sikkim","Chandigarh"],"a":0,"after":"It lights up Meghalaya."},"why":"A map question"},"st-fk.diengiei":{"route":"#/story/fk.diengiei","art":"art/story/fk-diengiei.jpg","cta":"Read the story","src":"story:fk.diengiei:scenes:0:text","title":"The Tree That Shaded the Whole World","body":"After the seven families had settled the earth, the Khasi telling says, a tree began to grow in the west. U Diengiei, it was called. It did not stop growing.","why":"From The Eastern Hills"},"sh-fk.diengiei":{"route":"#/story/fk.diengiei","art":null,"cta":"Read the story","src":"story:fk.diengiei:hook","title":"The Tree That Shaded the Whole World","body":"They cut it all day, every day. Every morning the cut had healed. Somebody was mending it in the dark.","why":"From The Eastern Hills"},"sm-fk.diengiei":{"route":"#/story/fk.diengiei","art":null,"cta":"Read the story","src":"story:fk.diengiei:scenes:4:text","title":"The Tree That Shaded the Whole World — the middle","body":"A little bird — one of the smallest in the forest, the kind nobody asks — hopped up and said: \"I see the nights, you know. U Khla the tiger comes when you leave. He loves the great darkness, for the forest under this shadow is all his.","why":"A moment from The Tree That Shaded the Whole World"},"sl-fk.diengiei":{"route":"#/story/fk.diengiei","art":null,"cta":"Read the story","src":"story:fk.diengiei:moral","title":"What The Tree That Shaded the Whole World says","body":"When your day's work keeps coming undone overnight, find out who is licking the cut.","why":"The story’s own lesson"},"sw-fk.diengiei-0":{"route":"#/story/fk.diengiei","art":null,"cta":"Read the story","src":"story:fk.diengiei:words_hi:0","title":"A Hindi word from The Tree That Shaded the Whole World","text":"कुल्हाड़ी","roman":"kulhaadi","lang":"hi","play":{"q":"What does it mean?","opts":["axe","squirrel","belief"],"a":0,"after":"कुल्हाड़ी (kulhaadi) means “axe”."},"why":"A word from The Tree That Shaded the Whole World"},"sw-fk.diengiei-1":{"route":"#/story/fk.diengiei","art":null,"cta":"Read the story","src":"story:fk.diengiei:words_hi:1","title":"A Hindi word from The Tree That Shaded the Whole World","text":"रोशनी","roman":"roshni","lang":"hi","play":{"q":"What does it mean?","opts":["light","sisters","answer"],"a":0,"after":"रोशनी (roshni) means “light”."},"why":"A word from The Tree That Shaded the Whole World"},"sp-fk.diengiei":{"route":"#/story/fk.diengiei","art":null,"cta":"Read the story","src":"story:fk.diengiei:place:0","title":"The Tree That Shaded the Whole World","play":{"q":"Which place on the map does this story light up?","opts":["Meghalaya","Andaman & Nicobar Islands","Himachal Pradesh"],"a":0,"after":"It lights up Meghalaya."},"why":"A map question"},"st-fk.klew-peacock":{"route":"#/story/fk.klew-peacock","art":"art/story/fk-klew-peacock.jpg","cta":"Read the story","src":"story:fk.klew-peacock:scenes:0:text","title":"Why the Peacock's Tail Is Full of Eyes","body":"In the Khasi telling, the sun is Ka Sngi — Ka, because she is a she; in Khasi, every name carries a U for a he or a Ka for a she, so you always know who you are talking about.","why":"From The Eastern Hills"},"sh-fk.klew-peacock":{"route":"#/story/fk.klew-peacock","art":null,"cta":"Read the story","src":"story:fk.klew-peacock:hook","title":"Why the Peacock's Tail Is Full of Eyes","body":"He lived in the sky and was loved there. He went down to earth for one look — and the eyes on his tail are what happened next.","why":"From The Eastern Hills"},"sm-fk.klew-peacock":{"route":"#/story/fk.klew-peacock","art":null,"cta":"Read the story","src":"story:fk.klew-peacock:scenes:4:text","title":"Why the Peacock's Tail Is Full of Eyes — the middle","body":"Up above, the sun's daughter watched the road of air every dawn. He did not come. Too far gone to return, too proud to be seen climbing home shabby and late — that is a knot many hearts have tied, and a peacock's heart is no different.","why":"A moment from Why the Peacock's Tail Is Full of Eyes"},"sl-fk.klew-peacock":{"route":"#/story/fk.klew-peacock","art":null,"cta":"Read the story","src":"story:fk.klew-peacock:moral","title":"What Why the Peacock's Tail Is Full of Eyes says","body":"Wander if you must. The ones who love you will pin their light to your feathers, and it will show.","why":"The story’s own lesson"},"sw-fk.klew-peacock-2":{"route":"#/story/fk.klew-peacock","art":null,"cta":"Read the story","src":"story:fk.klew-peacock:words_hi:2","title":"A Hindi word from Why the Peacock's Tail Is Full of Eyes","text":"पंख","roman":"pankh","lang":"hi","play":{"q":"What does it mean?","opts":["feather","sisters","answer"],"a":0,"after":"पंख (pankh) means “feather”."},"why":"A word from Why the Peacock's Tail Is Full of Eyes"},"sp-fk.klew-peacock":{"route":"#/story/fk.klew-peacock","art":null,"cta":"Read the story","src":"story:fk.klew-peacock:place:0","title":"Why the Peacock's Tail Is Full of Eyes","play":{"q":"Which place on the map does this story light up?","opts":["Meghalaya","Daman & Diu","Lakshadweep"],"a":0,"after":"It lights up Meghalaya."},"why":"A map question"},"st-fk.ksew-market":{"route":"#/story/fk.ksew-market","art":"art/story/fk-ksew-market.jpg","cta":"Read the story","src":"story:fk.ksew-market:scenes:0:text","title":"Why the Dog Sniffs Everybody","body":"Long ago in the Khasi hills, the telling goes, the animals held a great iew — a market, for market days are the heartbeat of these hills — and every animal kept a stall. The deer sold greens. The monkey sold fruit. Everyone sold something, and everyone came.","why":"From The Eastern Hills"},"sh-fk.ksew-market":{"route":"#/story/fk.ksew-market","art":null,"cta":"Read the story","src":"story:fk.ksew-market:hook","title":"Why the Dog Sniffs Everybody","body":"Once the dog kept a market stall like all the other animals. What they did to his stall is why he lives with you now.","why":"From The Eastern Hills"},"sm-fk.ksew-market":{"route":"#/story/fk.ksew-market","art":null,"cta":"Read the story","src":"story:fk.ksew-market:scenes:4:text","title":"Why the Dog Sniffs Everybody — the middle","body":"He walked until dark and came to the houses of people, and stood at the edge of the firelight with his ears uncertain. A man looked up from his supper, looked at him properly — the first creature all day to look at him properly — and moved over. \"Sit. There is enough.\"","why":"A moment from Why the Dog Sniffs Everybody"},"sl-fk.ksew-market":{"route":"#/story/fk.ksew-market","art":null,"cta":"Read the story","src":"story:fk.ksew-market:moral","title":"What Why the Dog Sniffs Everybody says","body":"If the crowd laughs at what you made, take yourself where you will be welcomed — and let the crowd wonder where the loyalty went.","why":"The story’s own lesson"},"sw-fk.ksew-market-2":{"route":"#/story/fk.ksew-market","art":null,"cta":"Read the story","src":"story:fk.ksew-market:words_hi:2","title":"A Hindi word from Why the Dog Sniffs Everybody","text":"सूँघना","roman":"soonghna","lang":"hi","play":{"q":"What does it mean?","opts":["to sniff","storm wind","blessing"],"a":0,"after":"सूँघना (soonghna) means “to sniff”."},"why":"A word from Why the Dog Sniffs Everybody"},"sp-fk.ksew-market":{"route":"#/story/fk.ksew-market","art":null,"cta":"Read the story","src":"story:fk.ksew-market:place:0","title":"Why the Dog Sniffs Everybody","play":{"q":"Which place on the map does this story light up?","opts":["Meghalaya","Jharkhand","Punjab"],"a":0,"after":"It lights up Meghalaya."},"why":"A map question"},"st-fk.root-bridges":{"route":"#/story/fk.root-bridges","art":"art/story/fk-root-bridges.jpg","cta":"Read the story","src":"story:fk.root-bridges:scenes:0:text","title":"The Bridge That Is Alive","body":"The southern slopes of Meghalaya, around Sohra, are the rainiest inhabited place on earth. It does not rain there the way it rains where you live. The rivers rise like something waking up, and they can take a bridge the way you take a biscuit.","why":"From The Eastern Hills"},"sh-fk.root-bridges":{"route":"#/story/fk.root-bridges","art":null,"cta":"Read the story","src":"story:fk.root-bridges:hook","title":"The Bridge That Is Alive","body":"Wood rots here in a season and iron rusts in two. So they build their bridges out of something that heals.","why":"From The Eastern Hills"},"sm-fk.root-bridges":{"route":"#/story/fk.root-bridges","art":null,"cta":"Read the story","src":"story:fk.root-bridges:scenes:4:text","title":"The Bridge That Is Alive — the middle","body":"A grandmother stands with a child, winding a young root onto the weave. \"Whose bridge is this, then?\" the child asks. \"Yours,\" she says. \"And you are working on it for someone who is not born yet. That is not strange. That is just what a bridge is, taken seriously.\"","why":"A moment from The Bridge That Is Alive"},"sl-fk.root-bridges":{"route":"#/story/fk.root-bridges","art":null,"cta":"Read the story","src":"story:fk.root-bridges:moral","title":"What The Bridge That Is Alive says","body":"Plant things your grandchildren will walk on.","why":"The story’s own lesson"},"sp-fk.root-bridges":{"route":"#/story/fk.root-bridges","art":null,"cta":"Read the story","src":"story:fk.root-bridges:place:0","title":"The Bridge That Is Alive","play":{"q":"Which place on the map does this story light up?","opts":["Meghalaya","Manipur","Uttarakhand"],"a":0,"after":"It lights up Meghalaya."},"why":"A map question"},"st-fk.wangala":{"route":"#/story/fk.wangala","art":"art/story/fk-wangala.jpg","cta":"Read the story","src":"story:fk.wangala:scenes:0:text","title":"A Hundred Drums Say Thank You","body":"The western half of Meghalaya belongs to the Garo people — who call themselves A·chik, the people of the hills.","why":"From The Eastern Hills"},"sh-fk.wangala":{"route":"#/story/fk.wangala","art":null,"cta":"Read the story","src":"story:fk.wangala:hook","title":"A Hundred Drums Say Thank You","body":"Nobody in the Garo hills tastes the new rice until the thank-you has been said. The thank-you takes a hundred drums.","why":"From The Eastern Hills"},"sm-fk.wangala":{"route":"#/story/fk.wangala","art":null,"cta":"Read the story","src":"story:fk.wangala:scenes:4:text","title":"A Hundred Drums Say Thank You — the middle","body":"The dancers wear feathered turbans that nod like grass, and the lines move together — step, dip, turn — young and old, the whole village in rows, with the flutes and gongs riding on top of the drum-thunder. It goes on for days. Thanks, done properly, takes a while.","why":"A moment from A Hundred Drums Say Thank You"},"sl-fk.wangala":{"route":"#/story/fk.wangala","art":null,"cta":"Read the story","src":"story:fk.wangala:moral","title":"What A Hundred Drums Say Thank You says","body":"Say thank you before you taste — and say it loud enough for the hills to hear.","why":"The story’s own lesson"},"sw-fk.wangala-1":{"route":"#/story/fk.wangala","art":null,"cta":"Read the story","src":"story:fk.wangala:words_hi:1","title":"A Hindi word from A Hundred Drums Say Thank You","text":"फ़सल","roman":"fasal","lang":"hi","play":{"q":"What does it mean?","opts":["harvest","squirrel","beginning"],"a":0,"after":"फ़सल (fasal) means “harvest”."},"why":"A word from A Hundred Drums Say Thank You"},"sp-fk.wangala":{"route":"#/story/fk.wangala","art":null,"cta":"Read the story","src":"story:fk.wangala:place:0","title":"A Hundred Drums Say Thank You","play":{"q":"Which place on the map does this story light up?","opts":["Meghalaya","Rajasthan","Bihar"],"a":0,"after":"It lights up Meghalaya."},"why":"A map question"},"st-fk.behdienkhlam":{"route":"#/story/fk.behdienkhlam","art":"art/story/fk-behdienkhlam.jpg","cta":"Read the story","src":"story:fk.behdienkhlam:scenes:0:text","title":"Chasing the Sickness Out of Town","body":"East of the Khasi hills live the Pnar — the Jaintia people, with their own speech and their own ways, and it is worth saying clearly: Khasi and Pnar are kin, not copies. Their great festival belongs to the town of Jowai, to the monsoon, and to a very old enemy.","why":"From The Eastern Hills"},"sh-fk.behdienkhlam":{"route":"#/story/fk.behdienkhlam","art":null,"cta":"Read the story","src":"story:fk.behdienkhlam:hook","title":"Chasing the Sickness Out of Town","body":"You cannot see sickness to chase it. The town of Jowai chases it anyway — with towers, drums, and a great deal of mud.","why":"From The Eastern Hills"},"sm-fk.behdienkhlam":{"route":"#/story/fk.behdienkhlam","art":null,"cta":"Read the story","src":"story:fk.behdienkhlam:scenes:4:text","title":"Chasing the Sickness Out of Town — the middle","body":"Meanwhile the rots have been building for days: tall towers of bamboo and coloured paper, each neighbourhood raising its own, each year's finer than last year's. On the great day they are carried on shoulders through the town, swaying like trees that have learned to walk.","why":"A moment from Chasing the Sickness Out of Town"},"sl-fk.behdienkhlam":{"route":"#/story/fk.behdienkhlam","art":null,"cta":"Read the story","src":"story:fk.behdienkhlam:moral","title":"What Chasing the Sickness Out of Town says","body":"What threatens everybody is chased by everybody. No roof gets skipped.","why":"The story’s own lesson"},"sw-fk.behdienkhlam-1":{"route":"#/story/fk.behdienkhlam","art":null,"cta":"Read the story","src":"story:fk.behdienkhlam:words_hi:1","title":"A Hindi word from Chasing the Sickness Out of Town","text":"गेंद","roman":"gend","lang":"hi","play":{"q":"What does it mean?","opts":["ball","story","blue"],"a":0,"after":"गेंद (gend) means “ball”."},"why":"A word from Chasing the Sickness Out of Town"},"sp-fk.behdienkhlam":{"route":"#/story/fk.behdienkhlam","art":null,"cta":"Read the story","src":"story:fk.behdienkhlam:place:0","title":"Chasing the Sickness Out of Town","play":{"q":"Which place on the map does this story light up?","opts":["Meghalaya","West Bengal","Gujarat"],"a":0,"after":"It lights up Meghalaya."},"why":"A map question"},"st-fk.chemtatrawta":{"route":"#/story/fk.chemtatrawta","art":"art/story/fk-chemtatrawta.jpg","cta":"Read the story","src":"story:fk.chemtatrawta:scenes:0:text","title":"It All Started With a Lobster","body":"In Mizoram, when everything has gone wrong at once and nobody can say whose fault it is, somebody old will sigh and say: this is the lobster all over again. And this is the story they mean.","why":"From The Eastern Hills"},"sh-fk.chemtatrawta":{"route":"#/story/fk.chemtatrawta","art":null,"cta":"Read the story","src":"story:fk.chemtatrawta:hook","title":"It All Started With a Lobster","body":"A pinch on the hand, and by evening half the forest was in trouble. The court case took longer than the trouble did.","why":"From The Eastern Hills"},"sm-fk.chemtatrawta":{"route":"#/story/fk.chemtatrawta","art":null,"cta":"Read the story","src":"story:fk.chemtatrawta:scenes:5:text","title":"It All Started With a Lobster — the middle","body":"So now: an old woman with no fence, no cotton and nothing to carry water in, a village with its path churned to mud, one shocked bat, several thousand furious ants, a bruised hen, a felled bamboo grove, and one man by the stream sucking his pinched hand. All before lunch.","why":"A moment from It All Started With a Lobster"},"sl-fk.chemtatrawta":{"route":"#/story/fk.chemtatrawta","art":null,"cta":"Read the story","src":"story:fk.chemtatrawta:moral","title":"What It All Started With a Lobster says","body":"Trouble travels in a chain, and every link is somebody who acted before looking.","why":"The story’s own lesson"},"sw-fk.chemtatrawta-0":{"route":"#/story/fk.chemtatrawta","art":null,"cta":"Read the story","src":"story:fk.chemtatrawta:words_hi:0","title":"A Hindi word from It All Started With a Lobster","text":"क्यों","roman":"kyon","lang":"hi","play":{"q":"What does it mean?","opts":["why","sweet","bow"],"a":0,"after":"क्यों (kyon) means “why”."},"why":"A word from It All Started With a Lobster"},"sw-fk.chemtatrawta-1":{"route":"#/story/fk.chemtatrawta","art":null,"cta":"Read the story","src":"story:fk.chemtatrawta:words_hi:1","title":"A Hindi word from It All Started With a Lobster","text":"झींगा","roman":"jheenga","lang":"hi","play":{"q":"What does it mean?","opts":["lobster / prawn","task","broken"],"a":0,"after":"झींगा (jheenga) means “lobster / prawn”."},"why":"A word from It All Started With a Lobster"},"sw-fk.chemtatrawta-2":{"route":"#/story/fk.chemtatrawta","art":null,"cta":"Read the story","src":"story:fk.chemtatrawta:words_hi:2","title":"A Hindi word from It All Started With a Lobster","text":"बाँस","roman":"baans","lang":"hi","play":{"q":"What does it mean?","opts":["bamboo","task","broom"],"a":0,"after":"बाँस (baans) means “bamboo”."},"why":"A word from It All Started With a Lobster"},"sp-fk.chemtatrawta":{"route":"#/story/fk.chemtatrawta","art":null,"cta":"Read the story","src":"story:fk.chemtatrawta:place:0","title":"It All Started With a Lobster","play":{"q":"Which place on the map does this story light up?","opts":["Mizoram","Chhattisgarh","Ladakh"],"a":0,"after":"It lights up Mizoram."},"why":"A map question"},"st-fk.chhura-door":{"route":"#/story/fk.chhura-door","art":"art/story/fk-chhura-door.jpg","cta":"Read the story","src":"story:fk.chhura-door:scenes:0:text","title":"Chhura Minds the Door","body":"Mizoram's best-loved man never existed, or existed everywhere, which comes to the same thing. His name is Chhura — Chhurbura, in full — and he is a fool. Not a wicked fool, not a sad one: a magnificent one.","why":"From The Eastern Hills"},"sh-fk.chhura-door":{"route":"#/story/fk.chhura-door","art":null,"cta":"Read the story","src":"story:fk.chhura-door:hook","title":"Chhura Minds the Door","body":"They told him to watch the door while they were out. He watched it very well. He watched it all the way to the feast.","why":"From The Eastern Hills"},"sm-fk.chhura-door":{"route":"#/story/fk.chhura-door","art":null,"cta":"Read the story","src":"story:fk.chhura-door:scenes:4:text","title":"Chhura Minds the Door — the middle","body":"He lifted the door off its pegs, roped it flat onto his back like an enormous wooden rucksack, and set off over the ridge, taking the turns carefully on account of his corners.","why":"A moment from Chhura Minds the Door"},"sl-fk.chhura-door":{"route":"#/story/fk.chhura-door","art":null,"cta":"Read the story","src":"story:fk.chhura-door:moral","title":"What Chhura Minds the Door says","body":"Do what people mean, not only what they say — and if you must get it wrong, get it wrong so well that everyone laughs.","why":"The story’s own lesson"},"sw-fk.chhura-door-2":{"route":"#/story/fk.chhura-door","art":null,"cta":"Read the story","src":"story:fk.chhura-door:words_hi:2","title":"A Hindi word from Chhura Minds the Door","text":"दावत","roman":"daawat","lang":"hi","play":{"q":"What does it mean?","opts":["feast","the Yamuna","butterfly"],"a":0,"after":"दावत (daawat) means “feast”."},"why":"A word from Chhura Minds the Door"},"sp-fk.chhura-door":{"route":"#/story/fk.chhura-door","art":null,"cta":"Read the story","src":"story:fk.chhura-door:place:0","title":"Chhura Minds the Door","play":{"q":"Which place on the map does this story light up?","opts":["Mizoram","Haryana","Odisha"],"a":0,"after":"It lights up Mizoram."},"why":"A map question"},"st-fk.chhura-nahaia":{"route":"#/story/fk.chhura-nahaia","art":"art/story/fk-chhura-nahaia.jpg","cta":"Read the story","src":"story:fk.chhura-nahaia:scenes:0:text","title":"The Field That Hummed","body":"Chhura had a brother called Nahaia, and Nahaia was the other kind of famous: clever. Too clever, by about ten per cent, which is the most dangerous amount. Where Chhura took your words somewhere strange, Nahaia took your things somewhere his.","why":"From The Eastern Hills"},"sh-fk.chhura-nahaia":{"route":"#/story/fk.chhura-nahaia","art":null,"cta":"Read the story","src":"story:fk.chhura-nahaia:hook","title":"The Field That Hummed","body":"His clever brother tricked him into swapping fields. The catch in the bargain turned out to be made of honey.","why":"From The Eastern Hills"},"sm-fk.chhura-nahaia":{"route":"#/story/fk.chhura-nahaia","art":null,"cta":"Read the story","src":"story:fk.chhura-nahaia:scenes:4:text","title":"The Field That Hummed — the middle","body":"He watched them all afternoon, coming and going with their legs dusted gold. He did not shout at them or poke the nest, because it was obvious even to a fool — especially to a fool, perhaps — that they were workers at work.","why":"A moment from The Field That Hummed"},"sl-fk.chhura-nahaia":{"route":"#/story/fk.chhura-nahaia","art":null,"cta":"Read the story","src":"story:fk.chhura-nahaia:moral","title":"What The Field That Hummed says","body":"What the clever call a trap, the patient may find is a treasure — and the kind share the honey either way.","why":"The story’s own lesson"},"sp-fk.chhura-nahaia":{"route":"#/story/fk.chhura-nahaia","art":null,"cta":"Read the story","src":"story:fk.chhura-nahaia:place:0","title":"The Field That Hummed","play":{"q":"Which place on the map does this story light up?","opts":["Mizoram","Maharashtra","Tripura"],"a":0,"after":"It lights up Mizoram."},"why":"A map question"},"st-fk.ngaitei":{"route":"#/story/fk.ngaitei","art":"art/story/fk-ngaitei.jpg","cta":"Read the story","src":"story:fk.ngaitei:scenes:0:text","title":"Ngaitei and the River","body":"In a village above a deep green river lived a girl called Ngaitei, with her grandmother — her pi, as Mizo children say. Her father had been lost to that river long before she could remember him. Her pi's one rule was simple: fill your pot at the edge, and come straight up.","why":"From The Eastern Hills"},"sh-fk.ngaitei":{"route":"#/story/fk.ngaitei","art":null,"cta":"Read the story","src":"story:fk.ngaitei:hook","title":"Ngaitei and the River","body":"The river rose through the village slowly, patiently, not angry — looking for something. Her grandmother knew what.","why":"From The Eastern Hills"},"sm-fk.ngaitei":{"route":"#/story/fk.ngaitei","art":null,"cta":"Read the story","src":"story:fk.ngaitei:scenes:4:text","title":"Ngaitei and the River — the middle","body":"The rains came. And the river rose. It came up past its usual stones, then past the bathing place, then — slowly, patiently, street by street, not angry, which was somehow more serious than angry — into the village itself. It was looking for something.","why":"A moment from Ngaitei and the River"},"sl-fk.ngaitei":{"route":"#/story/fk.ngaitei","art":null,"cta":"Read the story","src":"story:fk.ngaitei:moral","title":"What Ngaitei and the River says","body":"Give back what belongs to the river, and keep what belongs to you — and be honest about which is which.","why":"The story’s own lesson"},"sw-fk.ngaitei-1":{"route":"#/story/fk.ngaitei","art":null,"cta":"Read the story","src":"story:fk.ngaitei:words_hi:1","title":"A Hindi word from Ngaitei and the River","text":"कंघी","roman":"kanghi","lang":"hi","play":{"q":"What does it mean?","opts":["comb","the nectar of life","carpenter"],"a":0,"after":"कंघी (kanghi) means “comb”."},"why":"A word from Ngaitei and the River"},"sw-fk.ngaitei-2":{"route":"#/story/fk.ngaitei","art":null,"cta":"Read the story","src":"story:fk.ngaitei:words_hi:2","title":"A Hindi word from Ngaitei and the River","text":"वापस","roman":"wapas","lang":"hi","play":{"q":"What does it mean?","opts":["given back","thirteen","chariot"],"a":0,"after":"वापस (wapas) means “given back”."},"why":"A word from Ngaitei and the River"},"sp-fk.ngaitei":{"route":"#/story/fk.ngaitei","art":null,"cta":"Read the story","src":"story:fk.ngaitei:place:0","title":"Ngaitei and the River","play":{"q":"Which place on the map does this story light up?","opts":["Mizoram","Puducherry","Assam"],"a":0,"after":"It lights up Mizoram."},"why":"A map question"},"st-fk.mauruangi":{"route":"#/story/fk.mauruangi","art":"art/story/fk-mauruangi.jpg","cta":"Read the story","src":"story:fk.mauruangi:scenes:0:text","title":"Mauruangi and the Silk-Cotton Tree","body":"Mauruangi's mother was gone. How, the old Mizo tellings say harshly, and tonight we will say only that she was gone, and that the river had her.","why":"From The Eastern Hills"},"sh-fk.mauruangi":{"route":"#/story/fk.mauruangi","art":null,"cta":"Read the story","src":"story:fk.mauruangi:hook","title":"Mauruangi and the Silk-Cotton Tree","body":"They fed her scraps and water, and she grew bright as a festival. Somebody was feeding her that nobody could see.","why":"From The Eastern Hills"},"sm-fk.mauruangi":{"route":"#/story/fk.mauruangi","art":null,"cta":"Read the story","src":"story:fk.mauruangi:scenes:5:text","title":"Mauruangi and the Silk-Cotton Tree — the middle","body":"And then, from that very bank, a tree came up. A phunchawng — the silk-cotton tree, the one that sets the hills on fire with red flowers before it bothers with a single leaf.","why":"A moment from Mauruangi and the Silk-Cotton Tree"},"sl-fk.mauruangi":{"route":"#/story/fk.mauruangi","art":null,"cta":"Read the story","src":"story:fk.mauruangi:moral","title":"What Mauruangi and the Silk-Cotton Tree says","body":"Love outlasts its shapes — fish, flower, tree, girl. Feed people; it comes back flowering.","why":"The story’s own lesson"},"sp-fk.mauruangi":{"route":"#/story/fk.mauruangi","art":null,"cta":"Read the story","src":"story:fk.mauruangi:place:0","title":"Mauruangi and the Silk-Cotton Tree","play":{"q":"Which place on the map does this story light up?","opts":["Mizoram","Uttar Pradesh","Goa"],"a":0,"after":"It lights up Mizoram."},"why":"A map question"},"st-fk.sichangneii":{"route":"#/story/fk.sichangneii","art":"art/story/fk-sichangneii.jpg","cta":"Read the story","src":"story:fk.sichangneii:scenes:0:text","title":"The Winged One","body":"The Mizo tellings speak of Sichangneii — winged and shining, a daughter of the sky country. Some say sky-maiden, some say bird-woman; the tellings are old enough to disagree.","why":"From The Eastern Hills"},"sh-fk.sichangneii":{"route":"#/story/fk.sichangneii","art":null,"cta":"Read the story","src":"story:fk.sichangneii:hook","title":"The Winged One","body":"He hid her wings in the thatch so she would stay. Years later, the children found something beautiful in the roof.","why":"From The Eastern Hills"},"sm-fk.sichangneii":{"route":"#/story/fk.sichangneii","art":null,"cta":"Read the story","src":"story:fk.sichangneii:scenes:4:text","title":"The Winged One — the middle","body":"Years in, the children were playing where children should not, up under the roof — and they found the beautiful thing. They brought it down to their mother, proud as anything: look what was hidden in our house.","why":"A moment from The Winged One"},"sl-fk.sichangneii":{"route":"#/story/fk.sichangneii","art":null,"cta":"Read the story","src":"story:fk.sichangneii:moral","title":"What The Winged One says","body":"Never hide someone's wings. What stays because it is free is the only staying worth having.","why":"The story’s own lesson"},"sw-fk.sichangneii-1":{"route":"#/story/fk.sichangneii","art":null,"cta":"Read the story","src":"story:fk.sichangneii:words_hi:1","title":"A Hindi word from The Winged One","text":"उड़ान","roman":"udaan","lang":"hi","play":{"q":"What does it mean?","opts":["flight","to hide","cold"],"a":0,"after":"उड़ान (udaan) means “flight”."},"why":"A word from The Winged One"},"sw-fk.sichangneii-2":{"route":"#/story/fk.sichangneii","art":null,"cta":"Read the story","src":"story:fk.sichangneii:words_hi:2","title":"A Hindi word from The Winged One","text":"पिंजरा","roman":"pinjra","lang":"hi","play":{"q":"What does it mean?","opts":["cage","treasure","craftsperson"],"a":0,"after":"पिंजरा (pinjra) means “cage”."},"why":"A word from The Winged One"},"sp-fk.sichangneii":{"route":"#/story/fk.sichangneii","art":null,"cta":"Read the story","src":"story:fk.sichangneii:place:0","title":"The Winged One","play":{"q":"Which place on the map does this story light up?","opts":["Mizoram","Chandigarh","Kerala"],"a":0,"after":"It lights up Mizoram."},"why":"A map question"},"st-fk.liandova":{"route":"#/story/fk.liandova","art":"art/story/fk-liandova.jpg","cta":"Read the story","src":"story:fk.liandova:scenes:0:text","title":"The Two Brothers and the Great Snake","body":"Liandova and his little brother Tuaisiala were orphans, and in the old hill villages an orphan's life was a cold seat by somebody else's fire.","why":"From The Eastern Hills"},"sh-fk.liandova":{"route":"#/story/fk.liandova","art":null,"cta":"Read the story","src":"story:fk.liandova:hook","title":"The Two Brothers and the Great Snake","body":"Two orphans the village barely fed. What they found inside the old python changed the village's mind — but not theirs.","why":"From The Eastern Hills"},"sm-fk.liandova":{"route":"#/story/fk.liandova","art":null,"cta":"Read the story","src":"story:fk.liandova:scenes:5:text","title":"The Two Brothers and the Great Snake — the middle","body":"Word travels uphill fast. By evening, people who had never once called the brothers to a fire were strolling past their hut, remarking on the weather, remembering warmly that they had always thought well of the boys. You have seen this done. It is not beautiful.","why":"A moment from The Two Brothers and the Great Snake"},"sl-fk.liandova":{"route":"#/story/fk.liandova","art":null,"cta":"Read the story","src":"story:fk.liandova:moral","title":"What The Two Brothers and the Great Snake says","body":"Keep your brother first when you have nothing, and your table open when you have everything.","why":"The story’s own lesson"},"sp-fk.liandova":{"route":"#/story/fk.liandova","art":null,"cta":"Read the story","src":"story:fk.liandova:place:0","title":"The Two Brothers and the Great Snake","play":{"q":"Which place on the map does this story light up?","opts":["Mizoram","Himachal Pradesh","Nagaland"],"a":0,"after":"It lights up Mizoram."},"why":"A map question"},"st-fk.chapchar-kut":{"route":"#/story/fk.chapchar-kut","art":"art/story/fk-chapchar-kut.jpg","cta":"Read the story","src":"story:fk.chapchar-kut:scenes:0:text","title":"The Festival of the Waiting","body":"The farming year in the Mizo hills begins with an enormous effort: a patch of bamboo forest is cut for the year's lo, the hill field. And then — nothing. The cut bamboo must lie and dry before the clearing can be burned and sown. That drying pause is called chapchar.","why":"From The Eastern Hills"},"sh-fk.chapchar-kut":{"route":"#/story/fk.chapchar-kut","art":null,"cta":"Read the story","src":"story:fk.chapchar-kut:hook","title":"The Festival of the Waiting","body":"The bamboo is cut, and now it must dry, and nobody can do anything but wait. So the Mizo hills dance the waiting.","why":"From The Eastern Hills"},"sm-fk.chapchar-kut":{"route":"#/story/fk.chapchar-kut","art":null,"cta":"Read the story","src":"story:fk.chapchar-kut:scenes:4:text","title":"The Festival of the Waiting — the middle","body":"There is khuallam too — the dance of the guests, danced in swaying lines with cloth draped over the shoulders, the dance with which visitors are drawn into the circle. A festival in these hills is judged by how completely a stranger stops being one.","why":"A moment from The Festival of the Waiting"},"sl-fk.chapchar-kut":{"route":"#/story/fk.chapchar-kut","art":null,"cta":"Read the story","src":"story:fk.chapchar-kut:moral","title":"What The Festival of the Waiting says","body":"When the work makes you wait, dance the waiting — and trust the rhythm more than your eyes.","why":"The story’s own lesson"},"sw-fk.chapchar-kut-0":{"route":"#/story/fk.chapchar-kut","art":null,"cta":"Read the story","src":"story:fk.chapchar-kut:words_hi:0","title":"A Hindi word from The Festival of the Waiting","text":"ताल","roman":"taal","lang":"hi","play":{"q":"What does it mean?","opts":["the beat","tide","clay pot"],"a":0,"after":"ताल (taal) means “the beat”."},"why":"A word from The Festival of the Waiting"},"sw-fk.chapchar-kut-2":{"route":"#/story/fk.chapchar-kut","art":null,"cta":"Read the story","src":"story:fk.chapchar-kut:words_hi:2","title":"A Hindi word from The Festival of the Waiting","text":"मेहमान","roman":"mehmaan","lang":"hi","play":{"q":"What does it mean?","opts":["guest","victory","daybreak"],"a":0,"after":"मेहमान (mehmaan) means “guest”."},"why":"A word from The Festival of the Waiting"},"sp-fk.chapchar-kut":{"route":"#/story/fk.chapchar-kut","art":null,"cta":"Read the story","src":"story:fk.chapchar-kut:place:0","title":"The Festival of the Waiting","play":{"q":"Which place on the map does this story light up?","opts":["Mizoram","Lakshadweep","Tamil Nadu"],"a":0,"after":"It lights up Mizoram."},"why":"A map question"},"st-fk.unakoti":{"route":"#/story/fk.unakoti","art":"art/story/fk-unakoti.jpg","cta":"Read the story","src":"story:fk.unakoti:scenes:0:text","title":"One Less Than a Crore","body":"In the forested north of Tripura there is a hillside that stops people mid-sentence.","why":"From The Eastern Hills"},"sh-fk.unakoti":{"route":"#/story/fk.unakoti","art":null,"cta":"Read the story","src":"story:fk.unakoti:hook","title":"One Less Than a Crore","body":"A whole hillside in Tripura is covered with enormous stone faces. There are two stories about how they got there, and both are told.","why":"From The Eastern Hills"},"sm-fk.unakoti":{"route":"#/story/fk.unakoti","art":null,"cta":"Read the story","src":"story:fk.unakoti:scenes:4:text","title":"One Less Than a Crore — the middle","body":"That is why, people say, the faces on the hill have that deep, unbothered calm: they are not statues, they are sleepers. And nobody at Unakoti will promise you they are not simply waiting for a louder morning.","why":"A moment from One Less Than a Crore"},"sl-fk.unakoti":{"route":"#/story/fk.unakoti","art":null,"cta":"Read the story","src":"story:fk.unakoti:moral","title":"What One Less Than a Crore says","body":"Wake when the journey wakes — and if you fall one short of a crore, look at the hillside you filled anyway.","why":"The story’s own lesson"},"sw-fk.unakoti-0":{"route":"#/story/fk.unakoti","art":null,"cta":"Read the story","src":"story:fk.unakoti:words_hi:0","title":"A Hindi word from One Less Than a Crore","text":"करोड़","roman":"karod","lang":"hi","play":{"q":"What does it mean?","opts":["a crore — ten million","treasure","craftsperson"],"a":0,"after":"करोड़ (karod) means “a crore — ten million”."},"why":"A word from One Less Than a Crore"},"sw-fk.unakoti-1":{"route":"#/story/fk.unakoti","art":null,"cta":"Read the story","src":"story:fk.unakoti:words_hi:1","title":"A Hindi word from One Less Than a Crore","text":"मूर्ति","roman":"moorti","lang":"hi","play":{"q":"What does it mean?","opts":["carved image","victory","debate"],"a":0,"after":"मूर्ति (moorti) means “carved image”."},"why":"A word from One Less Than a Crore"},"sp-fk.unakoti":{"route":"#/story/fk.unakoti","art":null,"cta":"Read the story","src":"story:fk.unakoti:place:0","title":"One Less Than a Crore","play":{"q":"Which place on the map does this story light up?","opts":["Tripura","Odisha","Arunachal Pradesh"],"a":0,"after":"It lights up Tripura."},"why":"A map question"},"st-fk.twipra-name":{"route":"#/story/fk.twipra-name","art":"art/story/fk-twipra-name.jpg","cta":"Read the story","src":"story:fk.twipra-name:scenes:0:text","title":"The Land Beside the Water","body":"A girl in Agartala had a cousin abroad who asked her, over a crackling phone line, a simple question: what does Tripura actually mean? And she realised she did not know. So she did the correct thing, which was to ask a grandparent.","why":"From The Eastern Hills"},"sh-fk.twipra-name":{"route":"#/story/fk.twipra-name","art":null,"cta":"Read the story","src":"story:fk.twipra-name:hook","title":"The Land Beside the Water","body":"She asked what \"Tripura\" means, and got two completely different answers — one from each grandparent. Both were right.","why":"From The Eastern Hills"},"sm-fk.twipra-name":{"route":"#/story/fk.twipra-name","art":null,"cta":"Read the story","src":"story:fk.twipra-name:scenes:4:text","title":"The Land Beside the Water — the middle","body":"So that is what she did. \"Grandmother says: the land beside the waters, in our own words. Grandfather says: the kings' chronicle ties it to the old royal line and the goddess. And they are both sitting here nodding, so I am not choosing.\"","why":"A moment from The Land Beside the Water"},"sl-fk.twipra-name":{"route":"#/story/fk.twipra-name","art":null,"cta":"Read the story","src":"story:fk.twipra-name:moral","title":"What The Land Beside the Water says","body":"Learn every name your home answers to. Each one is a door.","why":"The story’s own lesson"},"sp-fk.twipra-name":{"route":"#/story/fk.twipra-name","art":null,"cta":"Read the story","src":"story:fk.twipra-name:place:0","title":"The Land Beside the Water","play":{"q":"Which place on the map does this story light up?","opts":["Tripura","Uttarakhand","Dadra & Nagar Haveli"],"a":0,"after":"It lights up Tripura."},"why":"A map question"},"st-fk.kharchi-fourteen":{"route":"#/story/fk.kharchi-fourteen","art":"art/story/fk-kharchi-fourteen.jpg","cta":"Read the story","src":"story:fk.kharchi-fourteen:scenes:0:text","title":"The Week of the Fourteen Gods","body":"In Old Agartala, a little way out of Tripura's capital, stands a temple that holds something found nowhere else: the Chaturdasha Devata, the Fourteen Gods of Tripura, kept together as one family of the divine — the special guardians of the land since the days of its kings.","why":"From The Eastern Hills"},"sh-fk.kharchi-fourteen":{"route":"#/story/fk.kharchi-fourteen","art":null,"cta":"Read the story","src":"story:fk.kharchi-fourteen:hook","title":"The Week of the Fourteen Gods","body":"Fourteen gods, each with two names — and once a year the whole state comes to their house.","why":"From The Eastern Hills"},"sm-fk.kharchi-fourteen":{"route":"#/story/fk.kharchi-fourteen","art":null,"cta":"Read the story","src":"story:fk.kharchi-fourteen:scenes:4:text","title":"The Week of the Fourteen Gods — the middle","body":"Many elders will tell you the week is also a washing for the earth herself — that after the sowing season the land is tired and stained with work, and Kharchi cleanses her too.","why":"A moment from The Week of the Fourteen Gods"},"sl-fk.kharchi-fourteen":{"route":"#/story/fk.kharchi-fourteen","art":null,"cta":"Read the story","src":"story:fk.kharchi-fourteen:moral","title":"What The Week of the Fourteen Gods says","body":"Prayers in two languages reach the same ears.","why":"The story’s own lesson"},"sw-fk.kharchi-fourteen-1":{"route":"#/story/fk.kharchi-fourteen","art":null,"cta":"Read the story","src":"story:fk.kharchi-fourteen:words_hi:1","title":"A Hindi word from The Week of the Fourteen Gods","text":"पूजा","roman":"puja","lang":"hi","play":{"q":"What does it mean?","opts":["worship","vegetable","daybreak"],"a":0,"after":"पूजा (puja) means “worship”."},"why":"A word from The Week of the Fourteen Gods"},"sp-fk.kharchi-fourteen":{"route":"#/story/fk.kharchi-fourteen","art":null,"cta":"Read the story","src":"story:fk.kharchi-fourteen:place:0","title":"The Week of the Fourteen Gods","play":{"q":"Which place on the map does this story light up?","opts":["Tripura","Bihar","Karnataka"],"a":0,"after":"It lights up Tripura."},"why":"A map question"},"st-fk.garia-puja":{"route":"#/story/fk.garia-puja","art":"art/story/fk-garia-puja.jpg","cta":"Read the story","src":"story:fk.garia-puja:scenes:0:text","title":"The God Who Comes Up Your Steps","body":"When the new year turns in the hills of Tripura — mid-April, the same great turning the whole valley-and-hill world shares — the Tripuri, Jamatia and Reang communities keep the days of Garia, and Garia is not a god you go to. Garia comes to you.","why":"From The Eastern Hills"},"sh-fk.garia-puja":{"route":"#/story/fk.garia-puja","art":null,"cta":"Read the story","src":"story:fk.garia-puja:hook","title":"The God Who Comes Up Your Steps","body":"Some gods wait in temples. Garia comes dancing into your courtyard, and brings the drums with him.","why":"From The Eastern Hills"},"sm-fk.garia-puja":{"route":"#/story/fk.garia-puja","art":null,"cta":"Read the story","src":"story:fk.garia-puja:scenes:4:text","title":"The God Who Comes Up Your Steps — the middle","body":"Among the Jamatia people especially, Garia's days are kept with great seriousness — the community's own priests, the proper songs, the old order of things held carefully.","why":"A moment from The God Who Comes Up Your Steps"},"sl-fk.garia-puja":{"route":"#/story/fk.garia-puja","art":null,"cta":"Read the story","src":"story:fk.garia-puja:moral","title":"What The God Who Comes Up Your Steps says","body":"The best blessings do not wait to be visited. They come up your steps with drums.","why":"The story’s own lesson"},"sw-fk.garia-puja-0":{"route":"#/story/fk.garia-puja","art":null,"cta":"Read the story","src":"story:fk.garia-puja:words_hi:0","title":"A Hindi word from The God Who Comes Up Your Steps","text":"आँगन","roman":"aangan","lang":"hi","play":{"q":"What does it mean?","opts":["courtyard","victory","debate"],"a":0,"after":"आँगन (aangan) means “courtyard”."},"why":"A word from The God Who Comes Up Your Steps"},"sp-fk.garia-puja":{"route":"#/story/fk.garia-puja","art":null,"cta":"Read the story","src":"story:fk.garia-puja:place:0","title":"The God Who Comes Up Your Steps","play":{"q":"Which place on the map does this story light up?","opts":["Tripura","Gujarat","Madhya Pradesh"],"a":0,"after":"It lights up Tripura."},"why":"A map question"},"st-fk.rignai-loom":{"route":"#/story/fk.rignai-loom","art":"art/story/fk-rignai-loom.jpg","cta":"Read the story","src":"story:fk.rignai-loom:scenes:0:text","title":"The Loom Tied to the Weaver","body":"On verandas all over the hills of Tripura you will find a loom with no frame, no legs, and no machine anywhere in it. One end of the threads is tied to the wall or a post. The other end is a strap — and the strap goes around the weaver's own back.","why":"From The Eastern Hills"},"sh-fk.rignai-loom":{"route":"#/story/fk.rignai-loom","art":null,"cta":"Read the story","src":"story:fk.rignai-loom:hook","title":"The Loom Tied to the Weaver","body":"The loom has no frame and no legs. One end ties to the wall — and the other end is the weaver herself.","why":"From The Eastern Hills"},"sm-fk.rignai-loom":{"route":"#/story/fk.rignai-loom","art":null,"cta":"Read the story","src":"story:fk.rignai-loom:scenes:4:text","title":"The Loom Tied to the Weaver — the middle","body":"Girls learn young, beside their mothers — first watching, then winding thread, then the day the strap goes around their own back for the first time and the whole loom suddenly depends on how still they sit. \"The cloth feels your mood,\" a mother will say.","why":"A moment from The Loom Tied to the Weaver"},"sl-fk.rignai-loom":{"route":"#/story/fk.rignai-loom","art":null,"cta":"Read the story","src":"story:fk.rignai-loom:moral","title":"What The Loom Tied to the Weaver says","body":"The pattern remembers the people. Wear it, and you carry them with you.","why":"The story’s own lesson"},"sw-fk.rignai-loom-0":{"route":"#/story/fk.rignai-loom","art":null,"cta":"Read the story","src":"story:fk.rignai-loom:words_hi:0","title":"A Hindi word from The Loom Tied to the Weaver","text":"कपड़ा","roman":"kapda","lang":"hi","play":{"q":"What does it mean?","opts":["cloth","weather","doll"],"a":0,"after":"कपड़ा (kapda) means “cloth”."},"why":"A word from The Loom Tied to the Weaver"},"sw-fk.rignai-loom-1":{"route":"#/story/fk.rignai-loom","art":null,"cta":"Read the story","src":"story:fk.rignai-loom:words_hi:1","title":"A Hindi word from The Loom Tied to the Weaver","text":"बुनना","roman":"bunna","lang":"hi","play":{"q":"What does it mean?","opts":["to weave","why","drop"],"a":0,"after":"बुनना (bunna) means “to weave”."},"why":"A word from The Loom Tied to the Weaver"},"sp-fk.rignai-loom":{"route":"#/story/fk.rignai-loom","art":null,"cta":"Read the story","src":"story:fk.rignai-loom:place:0","title":"The Loom Tied to the Weaver","play":{"q":"Which place on the map does this story light up?","opts":["Tripura","Ladakh","Sikkim"],"a":0,"after":"It lights up Tripura."},"why":"A map question"},"st-fk.matabari-turtles":{"route":"#/story/fk.matabari-turtles","art":"art/story/fk-matabari-turtles.jpg","cta":"Read the story","src":"story:fk.matabari-turtles:scenes:0:text","title":"The Mother's House by the Turtle Lake","body":"In Udaipur, in the green south of Tripura, stands the state's most beloved temple: Tripura Sundari, the beautiful goddess of the land.","why":"From The Eastern Hills"},"sh-fk.matabari-turtles":{"route":"#/story/fk.matabari-turtles","art":null,"cta":"Read the story","src":"story:fk.matabari-turtles:hook","title":"The Mother's House by the Turtle Lake","body":"Beside the temple is a lake full of enormous old turtles, and nobody has ever fished it. Ask why, and you learn what the whole place means.","why":"From The Eastern Hills"},"sm-fk.matabari-turtles":{"route":"#/story/fk.matabari-turtles","art":null,"cta":"Read the story","src":"story:fk.matabari-turtles:scenes:4:text","title":"The Mother's House by the Turtle Lake — the middle","body":"Pilgrims and children crouch on the steps and feed them — puffed rice, flour balls bought at the gate — and the great shells come gliding up out of the green like slow blessings surfacing. A child at the ghat asked her father the obvious question: why does nobody ever fish here?","why":"A moment from The Mother's House by the Turtle Lake"},"sl-fk.matabari-turtles":{"route":"#/story/fk.matabari-turtles","art":null,"cta":"Read the story","src":"story:fk.matabari-turtles:moral","title":"What The Mother's House by the Turtle Lake says","body":"In the Mother's yard, even the slowest swimmer is safe.","why":"The story’s own lesson"},"sw-fk.matabari-turtles-2":{"route":"#/story/fk.matabari-turtles","art":null,"cta":"Read the story","src":"story:fk.matabari-turtles:words_hi:2","title":"A Hindi word from The Mother's House by the Turtle Lake","text":"मिठाई","roman":"mithai","lang":"hi","play":{"q":"What does it mean?","opts":["sweet","world","evening"],"a":0,"after":"मिठाई (mithai) means “sweet”."},"why":"A word from The Mother's House by the Turtle Lake"},"sp-fk.matabari-turtles":{"route":"#/story/fk.matabari-turtles","art":null,"cta":"Read the story","src":"story:fk.matabari-turtles:place:0","title":"The Mother's House by the Turtle Lake","play":{"q":"Which place on the map does this story light up?","opts":["Tripura","Nagaland","Andhra Pradesh"],"a":0,"after":"It lights up Tripura."},"why":"A map question"},"st-fk.bizhu":{"route":"#/story/fk.bizhu","art":"art/story/fk-bizhu.jpg","cta":"Read the story","src":"story:fk.bizhu:scenes:0:text","title":"Flowers on the Water at Dawn","body":"Among the peoples of Tripura are the Chakma — a community spread across Tripura, Mizoram and beyond, with their own language, their own script, and their Buddhist faith carried through every move their history forced on them.","why":"From The Eastern Hills"},"sh-fk.bizhu":{"route":"#/story/fk.bizhu","art":null,"cta":"Read the story","src":"story:fk.bizhu:hook","title":"Flowers on the Water at Dawn","body":"Before sunrise on new year's eve, Chakma children are down at the river with armfuls of flowers. The door of the house will not shut for two days.","why":"From The Eastern Hills"},"sm-fk.bizhu":{"route":"#/story/fk.bizhu","art":null,"cta":"Read the story","src":"story:fk.bizhu:scenes:4:text","title":"Flowers on the Water at Dawn — the middle","body":"And here is the rule that makes Bizhu Bizhu: on that day the door does not shut. Anyone may come in, and everyone who comes in is fed pajon — neighbour, stranger, the child from three houses down you have never liked, everyone.","why":"A moment from Flowers on the Water at Dawn"},"sl-fk.bizhu":{"route":"#/story/fk.bizhu","art":null,"cta":"Read the story","src":"story:fk.bizhu:moral","title":"What Flowers on the Water at Dawn says","body":"Begin the year with flowers on the water and a door that will not shut.","why":"The story’s own lesson"},"sw-fk.bizhu-2":{"route":"#/story/fk.bizhu","art":null,"cta":"Read the story","src":"story:fk.bizhu:words_hi:2","title":"A Hindi word from Flowers on the Water at Dawn","text":"बड़े","roman":"bade","lang":"hi","play":{"q":"What does it mean?","opts":["the elders","world","evening"],"a":0,"after":"बड़े (bade) means “the elders”."},"why":"A word from Flowers on the Water at Dawn"},"sp-fk.bizhu":{"route":"#/story/fk.bizhu","art":null,"cta":"Read the story","src":"story:fk.bizhu:place:0","title":"Flowers on the Water at Dawn","play":{"q":"Which place on the map does this story light up?","opts":["Tripura","Tamil Nadu","Delhi"],"a":0,"after":"It lights up Tripura."},"why":"A map question"},"st-sci-sarabhai":{"route":"#/story/sci-sarabhai","art":"art/story/sci-sarabhai.jpg","cta":"Read the story","src":"story:sci-sarabhai:scenes:0:text","title":"The Rocket in the Church","body":"Vikram Sarabhai was born in 1919 into a great mill-owning family of Ahmedabad, in Gujarat, and could have spent his life comfortably running factories.","why":"From Vigyan — The Scientists"},"sh-sci-sarabhai":{"route":"#/story/sci-sarabhai","art":null,"cta":"Read the story","src":"story:sci-sarabhai:hook","title":"The Rocket in the Church","body":"India's space programme began in a fishing village in Kerala — in a church, with rocket parts arriving by bicycle and bullock cart. There are photographs.","why":"From Vigyan — The Scientists"},"sm-sci-sarabhai":{"route":"#/story/sci-sarabhai","art":null,"cta":"Read the story","src":"story:sci-sarabhai:scenes:3:text","title":"The Rocket in the Church — the middle","body":"So India's space programme moved into a church.","why":"A moment from The Rocket in the Church"},"sl-sci-sarabhai":{"route":"#/story/sci-sarabhai","art":null,"cta":"Read the story","src":"story:sci-sarabhai:moral","title":"What The Rocket in the Church says","body":"Aim at the sky, and load the rocket on whatever the village actually has — a beginning that waits for perfect equipment never begins.","why":"The story’s own lesson"},"sw-sci-sarabhai-1":{"route":"#/story/sci-sarabhai","art":null,"cta":"Read the story","src":"story:sci-sarabhai:words_hi:1","title":"A Hindi word from The Rocket in the Church","text":"साइकिल","roman":"saikil","lang":"hi","play":{"q":"What does it mean?","opts":["bicycle","sage","a loss"],"a":0,"after":"साइकिल (saikil) means “bicycle”."},"why":"A word from The Rocket in the Church"},"sp-sci-sarabhai":{"route":"#/story/sci-sarabhai","art":null,"cta":"Read the story","src":"story:sci-sarabhai:place:0","title":"The Rocket in the Church","play":{"q":"Which place on the map does this story light up?","opts":["Kerala","Lakshadweep","Sikkim"],"a":0,"after":"It lights up Kerala."},"why":"A map question"},"sc-sarabhai":{"route":"#/avcard/sarabhai","art":null,"cta":"Open their card","src":"avatar:sarabhai:achievements:0","title":"Vikram Sarabhai","body":"Founded a physics laboratory in Ahmedabad in 1947, at twenty-eight, eleven days after independence.","why":"Someone from The Rocket in the Church"},"st-sci-kalam":{"route":"#/story/sci-kalam","art":"art/story/sci-kalam.jpg","cta":"Read the story","src":"story:sci-kalam:scenes:0:text","title":"The Newspaper Boy of Rameswaram","body":"Avul Pakir Jainulabdeen Abdul Kalam was born in 1931 in Rameswaram, the island temple-town at the very toe of Tamil Nadu, where his father owned a wooden boat that ferried pilgrims.","why":"From Vigyan — The Scientists"},"sh-sci-kalam":{"route":"#/story/sci-kalam","art":null,"cta":"Read the story","src":"story:sci-kalam:hook","title":"The Newspaper Boy of Rameswaram","body":"The train stopped stopping at his island town, so the newspapers came flying out of a moving carriage — into the hands of a boy who would one day fly rockets.","why":"From Vigyan — The Scientists"},"sm-sci-kalam":{"route":"#/story/sci-kalam","art":null,"cta":"Read the story","src":"story:sci-kalam:scenes:3:text","title":"The Newspaper Boy of Rameswaram — the middle","body":"The road ran through physics in Tiruchirappalli and aeronautical engineering in Madras, and into India's rocket programme in its bicycle-and-bullock-cart infancy. In time he was made project director of the SLV-3 — India's attempt to build a launcher of its very own.","why":"A moment from The Newspaper Boy of Rameswaram"},"sl-sci-kalam":{"route":"#/story/sci-kalam","art":null,"cta":"Read the story","src":"story:sci-kalam:moral","title":"What The Newspaper Boy of Rameswaram says","body":"The distance from a small town to the sky is real — and it is crossed at dawn, one caught bundle at a time.","why":"The story’s own lesson"},"sp-sci-kalam":{"route":"#/story/sci-kalam","art":null,"cta":"Read the story","src":"story:sci-kalam:place:0","title":"The Newspaper Boy of Rameswaram","play":{"q":"Which place on the map does this story light up?","opts":["Tamil Nadu","Himachal Pradesh","Mizoram"],"a":0,"after":"It lights up Tamil Nadu."},"why":"A map question"},"st-sci-tessy":{"route":"#/story/sci-tessy","art":"art/story/sci-tessy.jpg","cta":"Read the story","src":"story:sci-tessy:scenes:0:text","title":"The Engineer Who Steered the Fire","body":"Tessy Thomas was born in 1963 in Alappuzha, Kerala — a town of canals and coir — and named, her family has said, after Mother Teresa.","why":"From Vigyan — The Scientists"},"sh-sci-tessy":{"route":"#/story/sci-tessy","art":null,"cta":"Read the story","src":"story:sci-tessy:hook","title":"The Engineer Who Steered the Fire","body":"A rocket is easy to light and very hard to steer. When India needed someone to lead its longest-flying missile, the record shows who got the job.","why":"From Vigyan — The Scientists"},"sm-sci-tessy":{"route":"#/story/sci-tessy","art":null,"cta":"Read the story","src":"story:sci-tessy:scenes:3:text","title":"The Engineer Who Steered the Fire — the middle","body":"In 2011, Agni-IV flew successfully with Tessy Thomas as its project director — the first woman ever to lead an Indian missile project.","why":"A moment from The Engineer Who Steered the Fire"},"sl-sci-tessy":{"route":"#/story/sci-tessy","art":null,"cta":"Read the story","src":"story:sci-tessy:moral","title":"What The Engineer Who Steered the Fire says","body":"Lighting the fire is the easy part. Steering it — patiently, precisely, all the way to the far target — is the work of a lifetime.","why":"The story’s own lesson"},"sw-sci-tessy-2":{"route":"#/story/sci-tessy","art":null,"cta":"Read the story","src":"story:sci-tessy:words_hi:2","title":"A Hindi word from The Engineer Who Steered the Fire","text":"लक्ष्य","roman":"lakshya","lang":"hi","play":{"q":"What does it mean?","opts":["aim","sound","ball"],"a":0,"after":"लक्ष्य (lakshya) means “aim”."},"why":"A word from The Engineer Who Steered the Fire"},"sp-sci-tessy":{"route":"#/story/sci-tessy","art":null,"cta":"Read the story","src":"story:sci-tessy:place:0","title":"The Engineer Who Steered the Fire","play":{"q":"Which place on the map does this story light up?","opts":["Kerala","Punjab","Arunachal Pradesh"],"a":0,"after":"It lights up Kerala."},"why":"A map question"},"sc-tessy":{"route":"#/avcard/tessy","art":null,"cta":"Open their card","src":"avatar:tessy:achievements:0","title":"Tessy Thomas","body":"Joined DRDO in 1988 and spent twenty years on guidance — the hard part, after the loud part.","why":"Someone from The Engineer Who Steered the Fire"},"ep-mahabharata-22":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":22},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:21:cards:0:text","title":"The Mahabharata · Both Cousins Come Asking","body":"Everybody now went looking for allies, and the two cousins had the same idea on the same day, which is how they both ended up in Krishna's room in Dwaraka while he was asleep.","why":"The Mahabharata, night 22"},"eh-mahabharata-22":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":22},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:21:hook","title":"The Mahabharata · Both Cousins Come Asking","body":"One of them chose the army. One of them chose the man who would not fight.","why":"The Mahabharata, night 22"},"em-mahabharata-22":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":22},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:21:cards:5:text","title":"The Mahabharata · Both Cousins Come Asking — the middle","body":"Duryodhana sat forward. He had already done the sum. An entire army against one man who had just publicly promised not to fight — there was no possible way Arjuna took the man.","why":"The Mahabharata, night 22"},"ew-mahabharata-22":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":22},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:21:wonder","title":"Something to wonder about","body":"Arjuna could have had an entire army and chose instead one friend who had already said he would not fight. When is one person worth more than everything they could give you?","why":"The Mahabharata, night 22"},"ewd-mahabharata-22-1":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":22},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:21:words_hi:1","title":"A Hindi word from Both Cousins Come Asking","text":"सेना","roman":"sena","lang":"hi","play":{"q":"What does it mean?","opts":["army","earth, soil","poor"],"a":0,"after":"सेना (sena) means “army”."},"why":"A word from Both Cousins Come Asking"},"ewd-mahabharata-22-2":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":22},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:21:words_hi:2","title":"A Hindi word from Both Cousins Come Asking","text":"चुनना","roman":"chunna","lang":"hi","play":{"q":"What does it mean?","opts":["to choose","faith","quiet"],"a":0,"after":"चुनना (chunna) means “to choose”."},"why":"A word from Both Cousins Come Asking"},"ep-mahabharata-23":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":23},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:22:cards:0:text","title":"The Mahabharata · Five Villages","body":"Krishna went to Hastinapura himself, as a messenger, to try to stop it. The whole city came out onto the road to see him come in, which tells you how badly ordinary people wanted this not to happen.","why":"The Mahabharata, night 23"},"eh-mahabharata-23":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":23},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:22:hook","title":"The Mahabharata · Five Villages","body":"They came down from a kingdom to five villages. He would not give them one.","why":"The Mahabharata, night 23"},"em-mahabharata-23":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":23},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:22:cards:5:text","title":"The Mahabharata · Five Villages — the middle","body":"\"Not five villages,\" said Duryodhana. \"Not one village. Not one field. Not as much earth as you could stand a needle up in. They can come and take it if they think it is theirs.\"","why":"The Mahabharata, night 23"},"ew-mahabharata-23":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":23},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:22:wonder","title":"Something to wonder about","body":"Krishna said at the gate that nobody would be able to say afterwards that there had been no other way. Does it help anybody, later, to know that there was one?","why":"The Mahabharata, night 23"},"ewd-mahabharata-23-1":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":23},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:22:words_hi:1","title":"A Hindi word from Five Villages","text":"सुई","roman":"sui","lang":"hi","play":{"q":"What does it mean?","opts":["needle","earth, clay","poor"],"a":0,"after":"सुई (sui) means “needle”."},"why":"A word from Five Villages"},"ep-mahabharata-25":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":25},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:24:cards:0:text","title":"The Mahabharata · The Night Before","body":"Kurukshetra is flat, and dry, and enormous, and by the end of that week there were eighteen armies camped on it — eleven on one side and seven on the other, which tells you how the odds looked to anybody counting tents.","why":"The Mahabharata, night 25"},"eh-mahabharata-25":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":25},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:24:hook","title":"The Mahabharata · The Night Before","body":"They wrote the rules of the war themselves. Then they broke every one.","why":"The Mahabharata, night 25"},"em-mahabharata-25":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":25},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:24:cards:6:text","title":"The Mahabharata · The Night Before — the middle","body":"And then, before anything started, Yudhishthira took his armour off. He put down his weapons, got out of his chariot, and started walking, alone, across the empty ground towards the other army.","why":"The Mahabharata, night 25"},"ew-mahabharata-25":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":25},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:24:wonder","title":"Something to wonder about","body":"Both sides sat down together the night before and wrote the rules of their own war, in daylight, and meant every line. Why would people about to do a thing like that want rules for it?","why":"The Mahabharata, night 25"},"ewd-mahabharata-25-0":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":25},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:24:words_hi:0","title":"A Hindi word from The Night Before","text":"मैदान","roman":"maidan","lang":"hi","play":{"q":"What does it mean?","opts":["field","feast","republic"],"a":0,"after":"मैदान (maidan) means “field”."},"why":"A word from The Night Before"},"ep-mahabharata-28":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":28},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:27:cards:0:text","title":"The Mahabharata · The Boy Inside the Wheel","body":"On the thirteenth day Drona set out a formation shaped like a turning wheel, with the army spiralling inward, and there were only two men on the other side who knew how to break into it — Krishna and Arjuna.","why":"The Mahabharata, night 28"},"eh-mahabharata-28":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":28},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:27:hook","title":"The Mahabharata · The Boy Inside the Wheel","body":"He knew how to get in. Nobody had ever told him how to get out.","why":"The Mahabharata, night 28"},"em-mahabharata-28":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":28},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:27:cards:6:text","title":"The Mahabharata · The Boy Inside the Wheel — the middle","body":"They broke his bow. Then his chariot. Then his sword. He was fighting with a chariot wheel held over his head at the end, on foot, in the middle of all of them.","why":"The Mahabharata, night 28"},"ew-mahabharata-28":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":28},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:27:wonder","title":"Something to wonder about","body":"Nobody woke up that morning meaning to become the sort of person who would do that; it took about a week, one reasonable step at a time. Where in that week was the step that should have been refused?","why":"The Mahabharata, night 28"},"ewd-mahabharata-28-0":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":28},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:27:words_hi:0","title":"A Hindi word from The Boy Inside the Wheel","text":"चक्र","roman":"chakra","lang":"hi","play":{"q":"What does it mean?","opts":["a circle","flower","root"],"a":0,"after":"चक्र (chakra) means “a circle”."},"why":"A word from The Boy Inside the Wheel"},"ewd-mahabharata-28-1":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":28},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:27:words_hi:1","title":"A Hindi word from The Boy Inside the Wheel","text":"घेरा","roman":"ghera","lang":"hi","play":{"q":"What does it mean?","opts":["a ring","fragrance","salt"],"a":0,"after":"घेरा (ghera) means “a ring”."},"why":"A word from The Boy Inside the Wheel"},"ewd-mahabharata-28-2":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":28},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:27:words_hi:2","title":"A Hindi word from The Boy Inside the Wheel","text":"सोलह","roman":"solah","lang":"hi","play":{"q":"What does it mean?","opts":["sixteen","fruit","science"],"a":0,"after":"सोलह (solah) means “sixteen”."},"why":"A word from The Boy Inside the Wheel"},"ep-mahabharata-31":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":31},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:30:cards:0:text","title":"The Mahabharata · The Last Day","body":"On the eighteenth day there was almost nothing left of either army, and Duryodhana was alone. Every one of his brothers was gone. Bhishma was lying on his arrows. Drona was gone. Karna was gone. Shakuni, who had started it, was gone.","why":"The Mahabharata, night 31"},"eh-mahabharata-31":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":31},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:30:hook","title":"The Mahabharata · The Last Day","body":"They found him at the bottom of a lake, and called him out.","why":"The Mahabharata, night 31"},"em-mahabharata-31":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":31},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:30:cards:6:text","title":"The Mahabharata · The Last Day — the middle","body":"Duryodhana went down. And Balarama, Krishna's own brother, who had taught both of those men to use a mace, walked off that bank in a fury and would not speak to anybody, because he had watched his students cheat.","why":"The Mahabharata, night 31"},"ew-mahabharata-31":{"route":"#/epic/mahabharata","act":{"a":"episode","id":"mahabharata","n":31},"art":null,"cta":"Hear this night","src":"epic:mahabharata:episodes:30:wonder","title":"Something to wonder about","body":"Duryodhana asked the people standing over him what exactly any of them had won, and nobody on that field answered him. Was there anything they could have said?","why":"The Mahabharata, night 31"}});
